import { KHOA_BO_NHO_TAM_CUC_BO } from './config.js';
import { hienThiThongBao, hienThiTaiTrang, anTaiTrang, dinhDangNgayHienThi, dinhDangNgayISO, trichXuatSoLieu } from './utils.js';
import { khoiTaoGiaoDien, xayDungMenuGiaoDien, apDungGiaoDien, luuCauHinhGiaoDien, apDungGiaoDienNgauNhien } from './theme.js';
import { thucHienGoiApi, ghiNhanTuongTacApi, lamMoiThongKeCsdl, datCheDoUngDung, layCheDoUngDung } from './api.js';
import { kiemTraTenTrongBaoCao, taoCauTrucGuiBaoCao } from './report.js';

$(function() {
    // --- TRẠNG THÁI ỨNG DỤNG ---
    let danhSachNhanVien = []; 
    let baoCaoLichSuGanNhat = null; 
    let ngayBaoCaoLichSu = null; 
    let nhanVienHienTai = null;
    let nhanVienCanXoa = null;

    // --- KHỞI TẠO MODAL BOOTSTRAP ---
    const modalThemNv = new bootstrap.Modal('#modal-them-nhan-vien');
    const modalDanBaoCao = new bootstrap.Modal('#modal-dan-bao-cao');
    const modalSuaBaoCao = new bootstrap.Modal('#modal-sua-bao-cao');
    const modalDanNhieuBaoCao = new bootstrap.Modal('#modal-dan-nhieu-bao-cao');
    const modalXacNhanXoa = new bootstrap.Modal('#modal-xac-nhan-xoa');
    const modalXemBaoCaoCu = new bootstrap.Modal('#modal-xem-bao-cao-cu');

    // --- CẬP NHẬT THÔNG TIN BUILD ---
    const phienBanBuild = "v1.5.0-stable";
    const thoiGianBuildStr = "2026.01.06 17:01"; 
    $('#thoi-gian-build').text(thoiGianBuildStr);
    $('.build-version').text(phienBanBuild);

    // --- SYSTEM MONITOR WIDGET ---
    $('#btn-toggle-monitor').on('click', function() {
        const $panel = $('#system-monitor-panel');
        if ($panel.hasClass('show')) {
            $panel.removeClass('show');
            setTimeout(() => $panel.hide(), 300); // Wait for transition
        } else {
            $panel.show();
            // Small delay to allow display:block to apply before transition
            setTimeout(() => $panel.addClass('show'), 10);
        }
    });

    const capNhatWidgetDb = (trucTuyen, slNv, slBaoCao, slTruyCap) => {
        const $cham = $('#cham-trang-thai-db');
        const $chu = $('#chu-trang-thai-db');
        const $nv = $('#so-luong-nv-db');
        const $bc = $('#so-luong-bao-cao-db');
        const $luong = $('#luong-truy-cap-api');

        if (trucTuyen) {
            $cham.removeClass('offline').addClass('online');
            $chu.text('Online');
        } else {
            $cham.removeClass('online').addClass('offline');
            $chu.text('Offline');
        }
        if (slNv !== null) $nv.text(`${slNv} NV`);
        if (slBaoCao !== null) $bc.text(`${slBaoCao} Rpt`);
        if (slTruyCap !== null) $luong.text(`${slTruyCap}`);
    }

    const $vungDsNv = $('#vung-danh-sach-nv');

    const capNhatNutTaoBaoCao = () => {
        const daBaoCao = danhSachNhanVien.filter(nv => nv.trangThai !== 'Chưa báo cáo').length;
        const tongSo = danhSachNhanVien.length;
        $('#nut-tao-bao-cao').html(`Tạo & Lưu Báo Cáo (${daBaoCao}/${tongSo})`);
    };

    const hienThiDanhSachNhanVien = () => {
        if (danhSachNhanVien.length === 0) {
             $vungDsNv.html('<div class="text-center py-3 text-muted">Danh sách trống.</div>');
             capNhatNutTaoBaoCao();
             return;
        }

        let html = '<div class="row g-2">';
        danhSachNhanVien.forEach(nv => {
            let lopNut = 'nut-ten-nv btn';
            if (nv.kiemTraTen === false) lopNut += ' sai-ten';
            else if (nv.trangThai === 'Đã báo cáo') lopNut += ' da-bao-cao';
            else if (nv.trangThai === 'Off') lopNut += ' nghi';

            html += `
                <div class="col-6">
                    <div class="input-group shadow-sm" style="border-radius: 0.75rem; overflow: hidden;">
                        <button class="${lopNut}" data-nv-ten="${nv.ten}" title="${nv.ten}">
                            ${nv.ten}
                        </button>
                        <button class="btn nut-sua-nv nut-sua-nhanh-nv" data-nv-ten="${nv.ten}">
                            <i class="fa-solid fa-pen-to-square"></i>
                        </button>
                        <button class="btn nut-xoa-nv nut-xoa-nv-kich-hoat" data-nv-id="${nv._id}" data-nv-ten="${nv.ten}">
                            <i class="fa-solid fa-trash-can"></i>
                        </button>
                    </div>
                </div>
            `;
        });
        html += '</div>';
        $vungDsNv.html(html);
        capNhatNutTaoBaoCao();
    };

    const luuVaoBoNhoTam = () => {
        const homNayStr = dinhDangNgayISO(new Date());
        const duLieu = {
            ngay: homNayStr,
            duLieuNv: danhSachNhanVien.map(n => ({
                _id: n._id, baoCao: n.baoCao, trangThai: n.trangThai, kiemTraTen: n.kiemTraTen
            })),
            vanBanKetQua: $('#vung-ket-qua-bao-cao').val()
        };
        localStorage.setItem(KHOA_BO_NHO_TAM_CUC_BO, JSON.stringify(duLieu));
    };

    const khoiPhuTuBoNhoTam = () => {
        const duLieuTho = localStorage.getItem(KHOA_BO_NHO_TAM_CUC_BO);
        if (!duLieuTho) return false;
        try {
            const duLieu = JSON.parse(duLieuTho);
            if (duLieu.ngay !== dinhDangNgayISO(new Date())) {
                localStorage.removeItem(KHOA_BO_NHO_TAM_CUC_BO);
                return false;
            }
            duLieu.duLieuNv.forEach(itemTam => {
                const nv = danhSachNhanVien.find(n => n._id === itemTam._id);
                if (nv && itemTam.baoCao) {
                    nv.baoCao = itemTam.baoCao; 
                    nv.trangThai = itemTam.trangThai; 
                    nv.kiemTraTen = itemTam.kiemTraTen;
                }
            });
            hienThiDanhSachNhanVien();
            if(duLieu.vanBanKetQua) $('#vung-ket-qua-bao-cao').val(duLieu.vanBanKetQua);
            return true;
        } catch (e) { return false; }
    };

    const taiDuLieuTuServer = async () => {
        hienThiTaiTrang("Đang tải danh sách FOS...");
        try {
            ghiNhanTuongTacApi().catch(() => {});

            const duLieuGoc = await thucHienGoiApi('nhanvien?h={"$orderby": {"Ten": 1}}');
            datCheDoUngDung('online');
            danhSachNhanVien = duLieuGoc.map(item => ({
                _id: item._id, ten: item.Ten, gioiTinh: item.GioiTinh,
                chiTieu: parseInt(item.ChiTieu, 10) || 50, baoCao: '',
                trangThai: 'Chưa báo cáo', kiemTraTen: null
            }));

            hienThiDanhSachNhanVien();

            // Ẩn loader ngay khi danh sách nhân viên hiện ra để user thao tác ngay
            anTaiTrang(); 

            // Các công việc nền tiếp tục chạy ngầm sau khi user đã có thể thao tác
            khoiPhuTuBoNhoTam();
            lamMoiThongKeCsdl(capNhatWidgetDb).catch(() => {});
            khoiPhuPhienLamViec().catch(() => {});

        } catch (error) {
            datCheDoUngDung('offline');
            hienThiThongBao("Đang hoạt động ngoại tuyến", "info");
            try {
                const phanHoi = await fetch('fos.txt');
                const text = await phanHoi.text();
                danhSachNhanVien = text.split('\n').filter(l => l.trim()).map((line, index) => {
                    const parts = line.split('|');
                    return {
                        _id: `local_${index}`, ten: parts[0]?.trim(), gioiTinh: parts[1]?.trim(), 
                        chiTieu: parseInt(parts[2]?.trim() || '50'), baoCao: '', 
                        trangThai: 'Chưa báo cáo', kiemTraTen: null
                    };
                });
                hienThiDanhSachNhanVien();
                anTaiTrang();
                khoiPhuTuBoNhoTam();
            } catch (e) {
                anTaiTrang();
            }
        }
    };

    const khoiPhuPhienLamViec = async () => {
        const homNayStr = dinhDangNgayISO(new Date());

        try {
            const bcHomNay = await thucHienGoiApi(`report?q={"ngayBaoCao": "${homNayStr}"}`);
            if (bcHomNay.length > 0) {
                bcHomNay[0].baoCaoFOS.forEach(item => {
                    const nv = danhSachNhanVien.find(n => n.ten === item.tenNhanVien);
                    if (nv && nv.baoCao === '') {
                        nv.trangThai = (item.OFF === 0 || item.OFF === '0') ? 'Đã báo cáo' : 'Off';
                        nv.baoCao = item.rawReport || `Fos ${item.tenNhanVien} ${nv.trangThai === 'Off' ? 'OFF' : ''}`;
                    }
                });
                hienThiDanhSachNhanVien();
            }
        } catch (e) {}

        // Lấy mốc lịch sử thực sự cũ hơn hôm nay
        try {
            const truyVanLichSu = `{"ngayBaoCao": {"$lt": "${homNayStr}"}}`;
            const sapXepLichSu = `{"$orderby": {"ngayBaoCao": -1}}`;
            const dsBcCu = await thucHienGoiApi(`report?q=${truyVanLichSu}&h=${sapXepLichSu}&max=1`);

            if (dsBcCu.length > 0) {
                const bcLichSu = dsBcCu[0];
                baoCaoLichSuGanNhat = bcLichSu;
                ngayBaoCaoLichSu = bcLichSu.ngayBaoCao;
                baoCaoLichSuGanNhat.duLieuNvLichSu = bcLichSu.baoCaoFOS.map(item => ({
                    ten: item.tenNhanVien, 
                    mtdMC: item.chiSoHieuSuat.saleTrongThang
                }));

                let txt = `Chốt mốc ngày ${dinhDangNgayHienThi(ngayBaoCaoLichSu)}:\n`;
                baoCaoLichSuGanNhat.duLieuNvLichSu.forEach(n => txt += `${n.ten}: MTD ${n.mtdMC}\n`);
                $('#vung-ket-qua-bao-cao-cu').val(txt);
                thucHienTaoBaoCao(null, true);
            }
        } catch (e) {}
    };

    const luuBaoCaoLenServer = async (cauTruc, chayNgam = false) => {
        if (layCheDoUngDung() === 'offline') return;
        if (chayNgam) $('#chi-bao-dang-luu').css('display', 'flex');
        try {
            const kiemTra = await thucHienGoiApi(`report?q={"ngayBaoCao": "${cauTruc.ngayBaoCao}"}`);
            if (kiemTra.length > 0) await thucHienGoiApi(`report/${kiemTra[0]._id}`, 'PUT', cauTruc);
            else await thucHienGoiApi('report', 'POST', cauTruc);
            lamMoiThongKeCsdl(capNhatWidgetDb);
        } catch (error) {} finally { setTimeout(() => $('#chi-bao-dang-luu').fadeOut(), 1000); }
    };

    const thucHienTaoBaoCao = (e, chiXem = false) => {
        danhSachNhanVien.sort((a, b) => b.chiTieu - a.chiTieu);
        hienThiDanhSachNhanVien();
        const quanLy = 'TNH';
        const ngayHienThi = dinhDangNgayHienThi(new Date());
        let tMC = 0, tNTB = 0, tETB = 0, nvActive = 0, tPos = 0, tAE = 0;
        let dsChiTiet = [];
        const banDoLichSu = new Map();
        if (baoCaoLichSuGanNhat?.duLieuNvLichSu) baoCaoLichSuGanNhat.duLieuNvLichSu.forEach(n => banDoLichSu.set(n.ten, n));

        danhSachNhanVien.forEach(nv => {
            const bieuTuong = nv.gioiTinh === 'Nữ' ? '👵' : '👨';
            const bc = nv.baoCao;
            let mtd = trichXuatSoLieu(bc, 'MTD MC');
            let ntb = trichXuatSoLieu(bc, 'NTB'), etb = trichXuatSoLieu(bc, 'ETB');
            let mcNay = ntb + etb;
            if (mcNay === 0) mcNay = trichXuatSoLieu(bc, ['Tổng MC', 'MC']);

            if ((nv.trangThai === 'Off' || mcNay === 0) && mtd === 0 && baoCaoLichSuGanNhat) {
                const nvLichSu = banDoLichSu.get(nv.ten);
                mtd = nvLichSu ? (nvLichSu.mtdMC || 0) : 0;
            }

            if (nv.trangThai === 'Off') {
                const matchLyDo = bc.match(/^Fos\s+\S+\s+(.*)$/i);
                const lyDo = (matchLyDo && matchLyDo[1] && matchLyDo[1].toUpperCase() !== 'OFF') ? matchLyDo[1] : 'OFF';
                dsChiTiet.push(`${bieuTuong}${nv.ten}: ${lyDo}/${mtd}/${nv.chiTieu}`);
            } else {
                nvActive++;
                tMC += mcNay; tNTB += ntb; tETB += etb;
                tPos += trichXuatSoLieu(bc, 'Pos'); tAE += trichXuatSoLieu(bc, ['AE+', 'AE Plus']);
                dsChiTiet.push(`${bieuTuong}${nv.ten}: ${mcNay}/${mtd}/${nv.chiTieu}`);
            }
        });

        const nsbqNTB = (nvActive > 0) ? (tNTB / nvActive).toFixed(2) : '0.00';
        const nsbqETB = (nvActive > 0) ? (tETB / nvActive).toFixed(2) : '0.00';
        let ketQua = `${quanLy} ngày ${ngayHienThi}\n🔥${danhSachNhanVien.length} FOS – ${tMC} MC\n✅NTB: ${tNTB}\n✅NSBQ NTB: ${nsbqNTB}\n✅ETB: ${tETB}\n✅NSBQ ETB: ${nsbqETB}\n✅AE+: ${tAE}\n✅Pos: ${tPos}/${danhSachNhanVien.length * 3}\n\n⭐️Active ${nvActive}/${danhSachNhanVien.length}\n${dsChiTiet.join('\n')}`;
        $('#vung-ket-qua-bao-cao').val(ketQua);

        if (!chiXem) {
            const thongKe = { tongFOS: danhSachNhanVien.length, tongMC: tMC, tongNTB: tNTB, nsbqNTB, tongETB: tETB, nsbqETB, tongPosThucHien: tPos, posChiTieu: danhSachNhanVien.length * 3, activeFOS: nvActive, tongAEPlus: tAE };
            luuBaoCaoLenServer(taoCauTrucGuiBaoCao(danhSachNhanVien, baoCaoLichSuGanNhat, thongKe), true);
        }
    };

    // --- SỰ KIỆN GIAO DIỆN ---
    $('body').on('click', '.lua-chon-giao-dien', function(e) {
        e.preventDefault();
        const theme = $(this).data('theme');
        const mode = $(this).data('mode');
        const lop = `theme-${theme}-${mode}`;
        apDungGiaoDien(lop); 
        luuCauHinhGiaoDien(lop);
        hienThiThongBao(`Giao diện: ${theme} ${mode}`);
    });

    $('#nut-giao-dien-ngau-nhien').on('click', e => { 
        e.preventDefault(); 
        luuCauHinhGiaoDien('random'); 
        apDungGiaoDienNgauNhien(); 
    });

    $('#nut-luu-nv-moi').on('click', async () => {
        const ten = $('#ten-nv-modal').val().trim(), gt = $('#gioi-tinh-nv-modal').val(), ct = parseInt($('#chi-tieu-nv-modal').val()) || 0;
        if (ten && !danhSachNhanVien.some(n => n.ten.toLowerCase() === ten.toLowerCase())) {
            hienThiTaiTrang("Đang lưu nhân viên...");
            try { await thucHienGoiApi('nhanvien', 'POST', { Ten: ten, GioiTinh: gt, ChiTieu: ct }); modalThemNv.hide(); taiDuLieuTuServer(); }
            catch (e) { hienThiThongBao(e.message, 'error'); } finally { anTaiTrang(); }
        }
    });

    $vungDsNv.on('click', '.nut-xoa-nv-kich-hoat', function() {
        nhanVienCanXoa = { id: $(this).data('nv-id'), ten: $(this).data('nv-ten') };
        $('#noi-dung-xac-nhan-xoa').text(`Xoá nhân viên "${nhanVienCanXoa.ten}"?`);
        modalXacNhanXoa.show();
    });

    $('#nut-xac-nhan-xoa-vinh-vien').on('click', async () => {
        if (!nhanVienCanXoa) return;
        hienThiTaiTrang("Đang xoá vĩnh viễn...");
        try { await thucHienGoiApi(`nhanvien/${nhanVienCanXoa.id}`, 'DELETE'); taiDuLieuTuServer(); }
        catch (e) { hienThiThongBao(e.message, 'error'); } finally { anTaiTrang(); modalXacNhanXoa.hide(); }
    });

    $vungDsNv.on('click', '.nut-ten-nv', function() {
        nhanVienHienTai = $(this).data('nv-ten');
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { 
            $('#modalDanBaoCaoLabel').text(`Báo cáo của ${nhanVienHienTai}`); 
            $('#noi-dung-bao-cao-nhap').val(nv.baoCao); 
            modalDanBaoCao.show(); 
        }
    });

    $('#nut-luu-bao-cao-don').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const nd = $('#noi-dung-bao-cao-nhap').val();
            nv.baoCao = nd; nv.trangThai = 'Đã báo cáo'; kiemTraTenTrongBaoCao(nv, nd);
            hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide();
        }
    });

    $('#nut-danh-dau-off').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { nv.baoCao = `Fos ${nv.ten} OFF`; nv.trangThai = 'Off'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide(); }
    });

    $('#nut-xac-nhan-off-co-ly-do').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { nv.baoCao = `Fos ${nv.ten} ${$('#ly-do-off-nhap').val().trim() || 'OFF'}`; nv.trangThai = 'Off'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide(); }
    });

    $vungDsNv.on('click', '.nut-sua-nhanh-nv', function() {
        nhanVienHienTai = $(this).data('nv-ten');
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const bc = nv.baoCao;
            $('#tieu-de-modal-sua-bao-cao').text(`Sửa nhanh: ${nhanVienHienTai}`);
            $('#ntb-sua').val(trichXuatSoLieu(bc, 'NTB')); $('#etb-sua').val(trichXuatSoLieu(bc, 'ETB'));
            $('#pos-sua').val(trichXuatSoLieu(bc, 'Pos')); $('#aeplus-sua').val(trichXuatSoLieu(bc, ['AE+', 'AE Plus']));
            $('#mtd-sua').val(trichXuatSoLieu(bc, 'MTD MC'));
            modalSuaBaoCao.show();
        }
    });

    $('#nut-xac-nhan-sua-bao-cao').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const n = parseInt($('#ntb-sua').val()) || 0, e = parseInt($('#etb-sua').val()) || 0;
            nv.baoCao = `Fos ${nv.ten}\nTổng MC: ${n+e}\nNTB: ${n}\nETB: ${e}\nAE+: ${$('#aeplus-sua').val() || 0}\nPos: ${$('#pos-sua').val() || 0}\nMTD MC: ${$('#mtd-sua').val() || 0}`;
            nv.trangThai = 'Đã báo cáo'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalSuaBaoCao.hide();
        }
    });

    $('#nut-dan-tu-bo-nho').on('click', async () => {
        try { const t = await navigator.clipboard.readText(); if (t) $('#noi-dung-bao-cao-nhap').val(t); } catch(e) {}
    });

    $('#nut-dan-hang-loat').on('click', async () => {
        try { const t = await navigator.clipboard.readText(); if (t) $('#noi-dung-nhieu-bao-cao-nhap').val(t); } catch(e) {}
    });

    $('#nut-xu-ly-nhieu-bao-cao').on('click', () => {
        const vanBan = $('#noi-dung-nhieu-bao-cao-nhap').val().trim();
        if (!vanBan) return;
        const khoiBaoCao = vanBan.split(/(?=^Fos\s)/im); 
        khoiBaoCao.forEach(khoi => {
            const khoiTrim = khoi.trim();
            const nv = danhSachNhanVien.find(n => {
                const tenEscape = n.ten.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
                return new RegExp(`^Fos\\s+${tenEscape}(?=\\s|$)`, 'i').test(khoiTrim);
            });
            if (nv) { nv.baoCao = khoiTrim; nv.trangThai = 'Đã báo cáo'; kiemTraTenTrongBaoCao(nv, khoiTrim); }
        });
        modalDanNhieuBaoCao.hide(); hienThiDanhSachNhanVien(); luuVaoBoNhoTam();
        hienThiThongBao("Đã xử lý xong báo cáo hàng loạt.");
    });

    $('#nut-tao-bao-cao').on('click', () => thucHienTaoBaoCao());
    $('#nut-sao-chep').on('click', function() {
        const $btn = $(this);
        navigator.clipboard.writeText($('#vung-ket-qua-bao-cao').val()).then(() => {
            hienThiThongBao('Đã sao chép báo cáo vào bộ nhớ tạm!');
            $btn.html('<i class="fa-solid fa-check"></i> Đã chép').addClass('btn-success').removeClass('btn-primary');
            setTimeout(() => $btn.html('<i class="fa-regular fa-copy"></i> Sao chép').removeClass('btn-success').addClass('btn-primary'), 2000);
        });
    });
    $('#nut-xem-bao-cao-cu').on('click', () => modalXemBaoCaoCu.show());

    // KHỞI CHẠY
    khoiTaoGiaoDien(); 
    xayDungMenuGiaoDien(); 
    taiDuLieuTuServer(); 
});

import { KHOA_BO_NHO_TAM_CUC_BO } from './config.js';
import { hienThiThongBao, hienThiTaiTrang, anTaiTrang, dinhDangNgayHienThi, dinhDangNgayISO, trichXuatSoLieu } from './utils.js';
import { khoiTaoGiaoDien, xayDungMenuGiaoDien, apDungGiaoDien, luuCauHinhGiaoDien, apDungGiaoDienNgauNhien } from './theme.js';
import { thucHienGoiApi, ghiNhanTuongTacApi, lamMoiThongKeCsdl, datCheDoUngDung, layCheDoUngDung } from './api.js';
import { kiemTraTenTrongBaoCao, taoCauTrucGuiBaoCao } from './report.js';

$(function() {
    // --- TRẠNG THÁI ỨNG DỤNG ---
    let danhSachNhanVien = []; 
    let baoCaoLichSuGanNhat = null; 
    let ngayBaoCaoLichSu = null; 
    let nhanVienHienTai = null;
    let nhanVienCanXoa = null;

    // --- KHỞI TẠO MODAL BOOTSTRAP ---
    const modalThemNv = new bootstrap.Modal('#modal-them-nhan-vien');
    const modalDanBaoCao = new bootstrap.Modal('#modal-dan-bao-cao');
    const modalSuaBaoCao = new bootstrap.Modal('#modal-sua-bao-cao');
    const modalDanNhieuBaoCao = new bootstrap.Modal('#modal-dan-nhieu-bao-cao');
    const modalXacNhanXoa = new bootstrap.Modal('#modal-xac-nhan-xoa');
    const modalXemBaoCaoCu = new bootstrap.Modal('#modal-xem-bao-cao-cu');

    // --- CẬP NHẬT THÔNG TIN BUILD ---
    const phienBanBuild = "v1.5.0-stable";
    const thoiGianBuildStr = "2026.01.06 17:05"; 
    $('#thoi-gian-build').text(thoiGianBuildStr);
    $('.build-version').text(phienBanBuild);

    // --- SYSTEM MONITOR WIDGET ---
    $('#btn-toggle-monitor').on('click', function() {
        const $panel = $('#system-monitor-panel');
        if ($panel.hasClass('show')) {
            $panel.removeClass('show');
            setTimeout(() => $panel.hide(), 300); // Wait for transition
        } else {
            $panel.show();
            // Small delay to allow display:block to apply before transition
            setTimeout(() => $panel.addClass('show'), 10);
        }
    });

    const capNhatWidgetDb = (trucTuyen, slNv, slBaoCao, slTruyCap) => {
        const $cham = $('#cham-trang-thai-db');
        const $chu = $('#chu-trang-thai-db');
        const $nv = $('#so-luong-nv-db');
        const $bc = $('#so-luong-bao-cao-db');
        const $luong = $('#luong-truy-cap-api');

        if (trucTuyen) {
            $cham.removeClass('offline').addClass('online');
            $chu.text('Online');
        } else {
            $cham.removeClass('online').addClass('offline');
            $chu.text('Offline');
        }
        if (slNv !== null) $nv.text(`${slNv} NV`);
        if (slBaoCao !== null) $bc.text(`${slBaoCao} Rpt`);
        if (slTruyCap !== null) $luong.text(`${slTruyCap}`);
    }

    const $vungDsNv = $('#vung-danh-sach-nv');

    const capNhatNutTaoBaoCao = () => {
        const daBaoCao = danhSachNhanVien.filter(nv => nv.trangThai !== 'Chưa báo cáo').length;
        const tongSo = danhSachNhanVien.length;
        $('#nut-tao-bao-cao').html(`Tạo & Lưu Báo Cáo (${daBaoCao}/${tongSo})`);
    };

    const hienThiDanhSachNhanVien = () => {
        if (danhSachNhanVien.length === 0) {
             $vungDsNv.html('<div class="text-center py-3 text-muted">Danh sách trống.</div>');
             capNhatNutTaoBaoCao();
             return;
        }

        let html = '<div class="row g-2">';
        danhSachNhanVien.forEach(nv => {
            let lopNut = 'nut-ten-nv btn';
            if (nv.kiemTraTen === false) lopNut += ' sai-ten';
            else if (nv.trangThai === 'Đã báo cáo') lopNut += ' da-bao-cao';
            else if (nv.trangThai === 'Off') lopNut += ' nghi';

            html += `
                <div class="col-6">
                    <div class="input-group shadow-sm" style="border-radius: 0.75rem; overflow: hidden;">
                        <button class="${lopNut}" data-nv-ten="${nv.ten}" title="${nv.ten}">
                            ${nv.ten}
                        </button>
                        <button class="btn nut-sua-nv nut-sua-nhanh-nv" data-nv-ten="${nv.ten}">
                            <i class="fa-solid fa-pen-to-square"></i>
                        </button>
                        <button class="btn nut-xoa-nv nut-xoa-nv-kich-hoat" data-nv-id="${nv._id}" data-nv-ten="${nv.ten}">
                            <i class="fa-solid fa-trash-can"></i>
                        </button>
                    </div>
                </div>
            `;
        });
        html += '</div>';
        $vungDsNv.html(html);
        capNhatNutTaoBaoCao();
    };

    const luuVaoBoNhoTam = () => {
        const homNayStr = dinhDangNgayISO(new Date());
        const duLieu = {
            ngay: homNayStr,
            duLieuNv: danhSachNhanVien.map(n => ({
                _id: n._id, baoCao: n.baoCao, trangThai: n.trangThai, kiemTraTen: n.kiemTraTen
            })),
            vanBanKetQua: $('#vung-ket-qua-bao-cao').val()
        };
        localStorage.setItem(KHOA_BO_NHO_TAM_CUC_BO, JSON.stringify(duLieu));
    };

    const khoiPhuTuBoNhoTam = () => {
        const duLieuTho = localStorage.getItem(KHOA_BO_NHO_TAM_CUC_BO);
        if (!duLieuTho) return false;
        try {
            const duLieu = JSON.parse(duLieuTho);
            if (duLieu.ngay !== dinhDangNgayISO(new Date())) {
                localStorage.removeItem(KHOA_BO_NHO_TAM_CUC_BO);
                return false;
            }
            duLieu.duLieuNv.forEach(itemTam => {
                const nv = danhSachNhanVien.find(n => n._id === itemTam._id);
                if (nv && itemTam.baoCao) {
                    nv.baoCao = itemTam.baoCao; 
                    nv.trangThai = itemTam.trangThai; 
                    nv.kiemTraTen = itemTam.kiemTraTen;
                }
            });
            hienThiDanhSachNhanVien();
            if(duLieu.vanBanKetQua) $('#vung-ket-qua-bao-cao').val(duLieu.vanBanKetQua);
            return true;
        } catch (e) { return false; }
    };

    const taiDuLieuTuServer = async () => {
        hienThiTaiTrang("Đang tải danh sách FOS...");
        try {
            ghiNhanTuongTacApi().catch(() => {});

            const duLieuGoc = await thucHienGoiApi('nhanvien?h={"$orderby": {"Ten": 1}}');
            datCheDoUngDung('online');
            danhSachNhanVien = duLieuGoc.map(item => ({
                _id: item._id, ten: item.Ten, gioiTinh: item.GioiTinh,
                chiTieu: parseInt(item.ChiTieu, 10) || 50, baoCao: '',
                trangThai: 'Chưa báo cáo', kiemTraTen: null
            }));

            hienThiDanhSachNhanVien();

            // Ẩn loader ngay khi danh sách nhân viên hiện ra để user thao tác ngay
            anTaiTrang(); 

            // Các công việc nền tiếp tục chạy ngầm sau khi user đã có thể thao tác
            khoiPhuTuBoNhoTam();
            lamMoiThongKeCsdl(capNhatWidgetDb).catch(() => {});
            khoiPhuPhienLamViec().catch(() => {});

        } catch (error) {
            datCheDoUngDung('offline');
            hienThiThongBao("Đang hoạt động ngoại tuyến", "info");
            try {
                const phanHoi = await fetch('fos.txt');
                const text = await phanHoi.text();
                danhSachNhanVien = text.split('\n').filter(l => l.trim()).map((line, index) => {
                    const parts = line.split('|');
                    return {
                        _id: `local_${index}`, ten: parts[0]?.trim(), gioiTinh: parts[1]?.trim(), 
                        chiTieu: parseInt(parts[2]?.trim() || '50'), baoCao: '', 
                        trangThai: 'Chưa báo cáo', kiemTraTen: null
                    };
                });
                hienThiDanhSachNhanVien();
                anTaiTrang();
                khoiPhuTuBoNhoTam();
            } catch (e) {
                anTaiTrang();
            }
        }
    };

    const khoiPhuPhienLamViec = async () => {
        const homNayStr = dinhDangNgayISO(new Date());

        try {
            const bcHomNay = await thucHienGoiApi(`report?q={"ngayBaoCao": "${homNayStr}"}`);
            if (bcHomNay.length > 0) {
                bcHomNay[0].baoCaoFOS.forEach(item => {
                    const nv = danhSachNhanVien.find(n => n.ten === item.tenNhanVien);
                    if (nv && nv.baoCao === '') {
                        nv.trangThai = (item.OFF === 0 || item.OFF === '0') ? 'Đã báo cáo' : 'Off';
                        nv.baoCao = item.rawReport || `Fos ${item.tenNhanVien} ${nv.trangThai === 'Off' ? 'OFF' : ''}`;
                    }
                });
                hienThiDanhSachNhanVien();
            }
        } catch (e) {}

        // Lấy mốc lịch sử thực sự cũ hơn hôm nay
        try {
            const truyVanLichSu = `{"ngayBaoCao": {"$lt": "${homNayStr}"}}`;
            const sapXepLichSu = `{"$orderby": {"ngayBaoCao": -1}}`;
            const dsBcCu = await thucHienGoiApi(`report?q=${truyVanLichSu}&h=${sapXepLichSu}&max=1`);

            if (dsBcCu.length > 0) {
                const bcLichSu = dsBcCu[0];
                baoCaoLichSuGanNhat = bcLichSu;
                ngayBaoCaoLichSu = bcLichSu.ngayBaoCao;
                baoCaoLichSuGanNhat.duLieuNvLichSu = bcLichSu.baoCaoFOS.map(item => ({
                    ten: item.tenNhanVien, 
                    mtdMC: item.chiSoHieuSuat.saleTrongThang
                }));

                let txt = `Chốt mốc ngày ${dinhDangNgayHienThi(ngayBaoCaoLichSu)}:\n`;
                baoCaoLichSuGanNhat.duLieuNvLichSu.forEach(n => txt += `${n.ten}: MTD ${n.mtdMC}\n`);
                $('#vung-ket-qua-bao-cao-cu').val(txt);
                thucHienTaoBaoCao(null, true);
            }
        } catch (e) {}
    };

    const luuBaoCaoLenServer = async (cauTruc, chayNgam = false) => {
        if (layCheDoUngDung() === 'offline') return;
        if (chayNgam) $('#chi-bao-dang-luu').css('display', 'flex');
        try {
            const kiemTra = await thucHienGoiApi(`report?q={"ngayBaoCao": "${cauTruc.ngayBaoCao}"}`);
            if (kiemTra.length > 0) await thucHienGoiApi(`report/${kiemTra[0]._id}`, 'PUT', cauTruc);
            else await thucHienGoiApi('report', 'POST', cauTruc);
            lamMoiThongKeCsdl(capNhatWidgetDb);
        } catch (error) {} finally { setTimeout(() => $('#chi-bao-dang-luu').fadeOut(), 1000); }
    };

    const thucHienTaoBaoCao = (e, chiXem = false) => {
        danhSachNhanVien.sort((a, b) => b.chiTieu - a.chiTieu);
        hienThiDanhSachNhanVien();
        const quanLy = 'TNH';
        const ngayHienThi = dinhDangNgayHienThi(new Date());
        let tMC = 0, tNTB = 0, tETB = 0, nvActive = 0, tPos = 0, tAE = 0;
        let dsChiTiet = [];
        const banDoLichSu = new Map();
        if (baoCaoLichSuGanNhat?.duLieuNvLichSu) baoCaoLichSuGanNhat.duLieuNvLichSu.forEach(n => banDoLichSu.set(n.ten, n));

        danhSachNhanVien.forEach(nv => {
            const bieuTuong = nv.gioiTinh === 'Nữ' ? '👵' : '👨';
            const bc = nv.baoCao;
            let mtd = trichXuatSoLieu(bc, 'MTD MC');
            let ntb = trichXuatSoLieu(bc, 'NTB'), etb = trichXuatSoLieu(bc, 'ETB');
            let mcNay = ntb + etb;
            if (mcNay === 0) mcNay = trichXuatSoLieu(bc, ['Tổng MC', 'MC']);

            if ((nv.trangThai === 'Off' || mcNay === 0) && mtd === 0 && baoCaoLichSuGanNhat) {
                const nvLichSu = banDoLichSu.get(nv.ten);
                mtd = nvLichSu ? (nvLichSu.mtdMC || 0) : 0;
            }

            if (nv.trangThai === 'Off') {
                const matchLyDo = bc.match(/^Fos\s+\S+\s+(.*)$/i);
                const lyDo = (matchLyDo && matchLyDo[1] && matchLyDo[1].toUpperCase() !== 'OFF') ? matchLyDo[1] : 'OFF';
                dsChiTiet.push(`${bieuTuong}${nv.ten}: ${lyDo}/${mtd}/${nv.chiTieu}`);
            } else {
                nvActive++;
                tMC += mcNay; tNTB += ntb; tETB += etb;
                tPos += trichXuatSoLieu(bc, 'Pos'); tAE += trichXuatSoLieu(bc, ['AE+', 'AE Plus']);
                dsChiTiet.push(`${bieuTuong}${nv.ten}: ${mcNay}/${mtd}/${nv.chiTieu}`);
            }
        });

        const nsbqNTB = (nvActive > 0) ? (tNTB / nvActive).toFixed(2) : '0.00';
        const nsbqETB = (nvActive > 0) ? (tETB / nvActive).toFixed(2) : '0.00';
        let ketQua = `${quanLy} ngày ${ngayHienThi}\n🔥${danhSachNhanVien.length} FOS – ${tMC} MC\n✅NTB: ${tNTB}\n✅NSBQ NTB: ${nsbqNTB}\n✅ETB: ${tETB}\n✅NSBQ ETB: ${nsbqETB}\n✅AE+: ${tAE}\n✅Pos: ${tPos}/${danhSachNhanVien.length * 3}\n\n⭐️Active ${nvActive}/${danhSachNhanVien.length}\n${dsChiTiet.join('\n')}`;
        $('#vung-ket-qua-bao-cao').val(ketQua);

        if (!chiXem) {
            const thongKe = { tongFOS: danhSachNhanVien.length, tongMC: tMC, tongNTB: tNTB, nsbqNTB, tongETB: tETB, nsbqETB, tongPosThucHien: tPos, posChiTieu: danhSachNhanVien.length * 3, activeFOS: nvActive, tongAEPlus: tAE };
            luuBaoCaoLenServer(taoCauTrucGuiBaoCao(danhSachNhanVien, baoCaoLichSuGanNhat, thongKe), true);
        }
    };

    // --- SỰ KIỆN GIAO DIỆN ---
    $('body').on('click', '.lua-chon-giao-dien', function(e) {
        e.preventDefault();
        const theme = $(this).data('theme');
        const mode = $(this).data('mode');
        const lop = `theme-${theme}-${mode}`;
        apDungGiaoDien(lop); 
        luuCauHinhGiaoDien(lop);
        hienThiThongBao(`Giao diện: ${theme} ${mode}`);
    });

    $('#nut-giao-dien-ngau-nhien').on('click', e => { 
        e.preventDefault(); 
        luuCauHinhGiaoDien('random'); 
        apDungGiaoDienNgauNhien(); 
    });

    $('#nut-luu-nv-moi').on('click', async () => {
        const ten = $('#ten-nv-modal').val().trim(), gt = $('#gioi-tinh-nv-modal').val(), ct = parseInt($('#chi-tieu-nv-modal').val()) || 0;
        if (ten && !danhSachNhanVien.some(n => n.ten.toLowerCase() === ten.toLowerCase())) {
            hienThiTaiTrang("Đang lưu nhân viên...");
            try { await thucHienGoiApi('nhanvien', 'POST', { Ten: ten, GioiTinh: gt, ChiTieu: ct }); modalThemNv.hide(); taiDuLieuTuServer(); }
            catch (e) { hienThiThongBao(e.message, 'error'); } finally { anTaiTrang(); }
        }
    });

    $vungDsNv.on('click', '.nut-xoa-nv-kich-hoat', function() {
        nhanVienCanXoa = { id: $(this).data('nv-id'), ten: $(this).data('nv-ten') };
        $('#noi-dung-xac-nhan-xoa').text(`Xoá nhân viên "${nhanVienCanXoa.ten}"?`);
        modalXacNhanXoa.show();
    });

    $('#nut-xac-nhan-xoa-vinh-vien').on('click', async () => {
        if (!nhanVienCanXoa) return;
        hienThiTaiTrang("Đang xoá vĩnh viễn...");
        try { await thucHienGoiApi(`nhanvien/${nhanVienCanXoa.id}`, 'DELETE'); taiDuLieuTuServer(); }
        catch (e) { hienThiThongBao(e.message, 'error'); } finally { anTaiTrang(); modalXacNhanXoa.hide(); }
    });

    $vungDsNv.on('click', '.nut-ten-nv', function() {
        nhanVienHienTai = $(this).data('nv-ten');
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { 
            $('#modalDanBaoCaoLabel').text(`Báo cáo của ${nhanVienHienTai}`); 
            $('#noi-dung-bao-cao-nhap').val(nv.baoCao); 
            modalDanBaoCao.show(); 
        }
    });

    $('#nut-luu-bao-cao-don').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const nd = $('#noi-dung-bao-cao-nhap').val();
            nv.baoCao = nd; nv.trangThai = 'Đã báo cáo'; kiemTraTenTrongBaoCao(nv, nd);
            hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide();
        }
    });

    $('#nut-danh-dau-off').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { nv.baoCao = `Fos ${nv.ten} OFF`; nv.trangThai = 'Off'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide(); }
    });

    $('#nut-xac-nhan-off-co-ly-do').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { nv.baoCao = `Fos ${nv.ten} ${$('#ly-do-off-nhap').val().trim() || 'OFF'}`; nv.trangThai = 'Off'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide(); }
    });

    $vungDsNv.on('click', '.nut-sua-nhanh-nv', function() {
        nhanVienHienTai = $(this).data('nv-ten');
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const bc = nv.baoCao;
            $('#tieu-de-modal-sua-bao-cao').text(`Sửa nhanh: ${nhanVienHienTai}`);
            $('#ntb-sua').val(trichXuatSoLieu(bc, 'NTB')); $('#etb-sua').val(trichXuatSoLieu(bc, 'ETB'));
            $('#pos-sua').val(trichXuatSoLieu(bc, 'Pos')); $('#aeplus-sua').val(trichXuatSoLieu(bc, ['AE+', 'AE Plus']));
            $('#mtd-sua').val(trichXuatSoLieu(bc, 'MTD MC'));
            modalSuaBaoCao.show();
        }
    });

    $('#nut-xac-nhan-sua-bao-cao').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const n = parseInt($('#ntb-sua').val()) || 0, e = parseInt($('#etb-sua').val()) || 0;
            nv.baoCao = `Fos ${nv.ten}\nTổng MC: ${n+e}\nNTB: ${n}\nETB: ${e}\nAE+: ${$('#aeplus-sua').val() || 0}\nPos: ${$('#pos-sua').val() || 0}\nMTD MC: ${$('#mtd-sua').val() || 0}`;
            nv.trangThai = 'Đã báo cáo'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalSuaBaoCao.hide();
        }
    });

    $('#nut-dan-tu-bo-nho').on('click', async () => {
        try { const t = await navigator.clipboard.readText(); if (t) $('#noi-dung-bao-cao-nhap').val(t); } catch(e) {}
    });

    $('#nut-dan-hang-loat').on('click', async () => {
        try { const t = await navigator.clipboard.readText(); if (t) $('#noi-dung-nhieu-bao-cao-nhap').val(t); } catch(e) {}
    });

    $('#nut-xu-ly-nhieu-bao-cao').on('click', () => {
        const vanBan = $('#noi-dung-nhieu-bao-cao-nhap').val().trim();
        if (!vanBan) return;
        const khoiBaoCao = vanBan.split(/(?=^Fos\s)/im); 
        khoiBaoCao.forEach(khoi => {
            const khoiTrim = khoi.trim();
            const nv = danhSachNhanVien.find(n => {
                const tenEscape = n.ten.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
                return new RegExp(`^Fos\\s+${tenEscape}(?=\\s|$)`, 'i').test(khoiTrim);
            });
            if (nv) { nv.baoCao = khoiTrim; nv.trangThai = 'Đã báo cáo'; kiemTraTenTrongBaoCao(nv, khoiTrim); }
        });
        modalDanNhieuBaoCao.hide(); hienThiDanhSachNhanVien(); luuVaoBoNhoTam();
        hienThiThongBao("Đã xử lý xong báo cáo hàng loạt.");
    });

    $('#nut-tao-bao-cao').on('click', () => thucHienTaoBaoCao());
    $('#nut-sao-chep').on('click', function() {
        const $btn = $(this);
        navigator.clipboard.writeText($('#vung-ket-qua-bao-cao').val()).then(() => {
            hienThiThongBao('Đã sao chép báo cáo vào bộ nhớ tạm!');
            $btn.html('<i class="fa-solid fa-check"></i> Đã chép').addClass('btn-success').removeClass('btn-primary');
            setTimeout(() => $btn.html('<i class="fa-regular fa-copy"></i> Sao chép').removeClass('btn-success').addClass('btn-primary'), 2000);
        });
    });
    $('#nut-xem-bao-cao-cu').on('click', () => modalXemBaoCaoCu.show());

    // KHỞI CHẠY
    khoiTaoGiaoDien(); 
    xayDungMenuGiaoDien(); 
    taiDuLieuTuServer(); 
});

import { KHOA_BO_NHO_TAM_CUC_BO } from './config.js';
import { hienThiThongBao, hienThiTaiTrang, anTaiTrang, dinhDangNgayHienThi, dinhDangNgayISO, trichXuatSoLieu } from './utils.js';
import { khoiTaoGiaoDien, xayDungMenuGiaoDien, apDungGiaoDien, luuCauHinhGiaoDien, apDungGiaoDienNgauNhien } from './theme.js';
import { thucHienGoiApi, ghiNhanTuongTacApi, lamMoiThongKeCsdl, datCheDoUngDung, layCheDoUngDung } from './api.js';
import { kiemTraTenTrongBaoCao, taoCauTrucGuiBaoCao } from './report.js';

$(function() {
    // --- TRẠNG THÁI ỨNG DỤNG ---
    let danhSachNhanVien = []; 
    let baoCaoLichSuGanNhat = null; 
    let ngayBaoCaoLichSu = null; 
    let nhanVienHienTai = null;
    let nhanVienCanXoa = null;

    // --- KHỞI TẠO MODAL BOOTSTRAP ---
    const modalThemNv = new bootstrap.Modal('#modal-them-nhan-vien');
    const modalDanBaoCao = new bootstrap.Modal('#modal-dan-bao-cao');
    const modalSuaBaoCao = new bootstrap.Modal('#modal-sua-bao-cao');
    const modalDanNhieuBaoCao = new bootstrap.Modal('#modal-dan-nhieu-bao-cao');
    const modalXacNhanXoa = new bootstrap.Modal('#modal-xac-nhan-xoa');
    const modalXemBaoCaoCu = new bootstrap.Modal('#modal-xem-bao-cao-cu');

    // --- CẬP NHẬT THÔNG TIN BUILD ---
    const phienBanBuild = "v1.5.0-stable";
    const thoiGianBuildStr = "2026.01.06 17:10"; 
    $('#thoi-gian-build').text(thoiGianBuildStr);
    $('.build-version').text(phienBanBuild);

    // --- SYSTEM MONITOR WIDGET ---
    $('#btn-toggle-monitor').on('click', function() {
        const $panel = $('#system-monitor-panel');
        if ($panel.hasClass('show')) {
            $panel.removeClass('show');
            setTimeout(() => $panel.hide(), 300); // Wait for transition
        } else {
            $panel.show();
            // Small delay to allow display:block to apply before transition
            setTimeout(() => $panel.addClass('show'), 10);
        }
    });

    const capNhatWidgetDb = (trucTuyen, slNv, slBaoCao, slTruyCap) => {
        const $cham = $('#cham-trang-thai-db');
        const $chu = $('#chu-trang-thai-db');
        const $nv = $('#so-luong-nv-db');
        const $bc = $('#so-luong-bao-cao-db');
        const $luong = $('#luong-truy-cap-api');

        if (trucTuyen) {
            $cham.removeClass('offline').addClass('online');
            $chu.text('Online');
        } else {
            $cham.removeClass('online').addClass('offline');
            $chu.text('Offline');
        }
        if (slNv !== null) $nv.text(`${slNv} NV`);
        if (slBaoCao !== null) $bc.text(`${slBaoCao} Rpt`);
        if (slTruyCap !== null) $luong.text(`${slTruyCap}`);
    }

    const $vungDsNv = $('#vung-danh-sach-nv');

    const capNhatNutTaoBaoCao = () => {
        const daBaoCao = danhSachNhanVien.filter(nv => nv.trangThai !== 'Chưa báo cáo').length;
        const tongSo = danhSachNhanVien.length;
        $('#nut-tao-bao-cao').html(`Tạo & Lưu Báo Cáo (${daBaoCao}/${tongSo})`);
    };

    const hienThiDanhSachNhanVien = () => {
        if (danhSachNhanVien.length === 0) {
             $vungDsNv.html('<div class="text-center py-3 text-muted">Danh sách trống.</div>');
             capNhatNutTaoBaoCao();
             return;
        }

        let html = '<div class="row g-2">';
        danhSachNhanVien.forEach(nv => {
            let lopNut = 'nut-ten-nv btn';
            if (nv.kiemTraTen === false) lopNut += ' sai-ten';
            else if (nv.trangThai === 'Đã báo cáo') lopNut += ' da-bao-cao';
            else if (nv.trangThai === 'Off') lopNut += ' nghi';

            html += `
                <div class="col-6">
                    <div class="input-group shadow-sm" style="border-radius: 0.75rem; overflow: hidden;">
                        <button class="${lopNut}" data-nv-ten="${nv.ten}" title="${nv.ten}">
                            ${nv.ten}
                        </button>
                        <button class="btn nut-sua-nv nut-sua-nhanh-nv" data-nv-ten="${nv.ten}">
                            <i class="fa-solid fa-pen-to-square"></i>
                        </button>
                        <button class="btn nut-xoa-nv nut-xoa-nv-kich-hoat" data-nv-id="${nv._id}" data-nv-ten="${nv.ten}">
                            <i class="fa-solid fa-trash-can"></i>
                        </button>
                    </div>
                </div>
            `;
        });
        html += '</div>';
        $vungDsNv.html(html);
        capNhatNutTaoBaoCao();
    };

    const luuVaoBoNhoTam = () => {
        const homNayStr = dinhDangNgayISO(new Date());
        const duLieu = {
            ngay: homNayStr,
            duLieuNv: danhSachNhanVien.map(n => ({
                _id: n._id, baoCao: n.baoCao, trangThai: n.trangThai, kiemTraTen: n.kiemTraTen
            })),
            vanBanKetQua: $('#vung-ket-qua-bao-cao').val()
        };
        localStorage.setItem(KHOA_BO_NHO_TAM_CUC_BO, JSON.stringify(duLieu));
    };

    const khoiPhuTuBoNhoTam = () => {
        const duLieuTho = localStorage.getItem(KHOA_BO_NHO_TAM_CUC_BO);
        if (!duLieuTho) return false;
        try {
            const duLieu = JSON.parse(duLieuTho);
            if (duLieu.ngay !== dinhDangNgayISO(new Date())) {
                localStorage.removeItem(KHOA_BO_NHO_TAM_CUC_BO);
                return false;
            }
            duLieu.duLieuNv.forEach(itemTam => {
                const nv = danhSachNhanVien.find(n => n._id === itemTam._id);
                if (nv && itemTam.baoCao) {
                    nv.baoCao = itemTam.baoCao; 
                    nv.trangThai = itemTam.trangThai; 
                    nv.kiemTraTen = itemTam.kiemTraTen;
                }
            });
            hienThiDanhSachNhanVien();
            if(duLieu.vanBanKetQua) $('#vung-ket-qua-bao-cao').val(duLieu.vanBanKetQua);
            return true;
        } catch (e) { return false; }
    };

    const taiDuLieuTuServer = async () => {
        hienThiTaiTrang("Đang tải danh sách FOS...");
        try {
            ghiNhanTuongTacApi().catch(() => {});

            const duLieuGoc = await thucHienGoiApi('nhanvien?h={"$orderby": {"Ten": 1}}');
            datCheDoUngDung('online');
            danhSachNhanVien = duLieuGoc.map(item => ({
                _id: item._id, ten: item.Ten, gioiTinh: item.GioiTinh,
                chiTieu: parseInt(item.ChiTieu, 10) || 50, baoCao: '',
                trangThai: 'Chưa báo cáo', kiemTraTen: null
            }));

            hienThiDanhSachNhanVien();

            // Ẩn loader ngay khi danh sách nhân viên hiện ra để user thao tác ngay
            anTaiTrang(); 

            // Các công việc nền tiếp tục chạy ngầm sau khi user đã có thể thao tác
            khoiPhuTuBoNhoTam();
            lamMoiThongKeCsdl(capNhatWidgetDb).catch(() => {});
            khoiPhuPhienLamViec().catch(() => {});

        } catch (error) {
            datCheDoUngDung('offline');
            hienThiThongBao("Đang hoạt động ngoại tuyến", "info");
            try {
                const phanHoi = await fetch('fos.txt');
                const text = await phanHoi.text();
                danhSachNhanVien = text.split('\n').filter(l => l.trim()).map((line, index) => {
                    const parts = line.split('|');
                    return {
                        _id: `local_${index}`, ten: parts[0]?.trim(), gioiTinh: parts[1]?.trim(), 
                        chiTieu: parseInt(parts[2]?.trim() || '50'), baoCao: '', 
                        trangThai: 'Chưa báo cáo', kiemTraTen: null
                    };
                });
                hienThiDanhSachNhanVien();
                anTaiTrang();
                khoiPhuTuBoNhoTam();
            } catch (e) {
                anTaiTrang();
            }
        }
    };

    const khoiPhuPhienLamViec = async () => {
        const homNayStr = dinhDangNgayISO(new Date());

        try {
            const bcHomNay = await thucHienGoiApi(`report?q={"ngayBaoCao": "${homNayStr}"}`);
            if (bcHomNay.length > 0) {
                bcHomNay[0].baoCaoFOS.forEach(item => {
                    const nv = danhSachNhanVien.find(n => n.ten === item.tenNhanVien);
                    if (nv && nv.baoCao === '') {
                        nv.trangThai = (item.OFF === 0 || item.OFF === '0') ? 'Đã báo cáo' : 'Off';
                        nv.baoCao = item.rawReport || `Fos ${item.tenNhanVien} ${nv.trangThai === 'Off' ? 'OFF' : ''}`;
                    }
                });
                hienThiDanhSachNhanVien();
            }
        } catch (e) {}

        // Lấy mốc lịch sử thực sự cũ hơn hôm nay
        try {
            const truyVanLichSu = `{"ngayBaoCao": {"$lt": "${homNayStr}"}}`;
            const sapXepLichSu = `{"$orderby": {"ngayBaoCao": -1}}`;
            const dsBcCu = await thucHienGoiApi(`report?q=${truyVanLichSu}&h=${sapXepLichSu}&max=1`);

            if (dsBcCu.length > 0) {
                const bcLichSu = dsBcCu[0];
                baoCaoLichSuGanNhat = bcLichSu;
                ngayBaoCaoLichSu = bcLichSu.ngayBaoCao;
                baoCaoLichSuGanNhat.duLieuNvLichSu = bcLichSu.baoCaoFOS.map(item => ({
                    ten: item.tenNhanVien, 
                    mtdMC: item.chiSoHieuSuat.saleTrongThang
                }));
                thucHienTaoBaoCao(null, true);
            }
        } catch (e) {}
    };

    const luuBaoCaoLenServer = async (cauTruc, chayNgam = false) => {
        if (layCheDoUngDung() === 'offline') return;
        if (chayNgam) $('#chi-bao-dang-luu').css('display', 'flex');
        try {
            const kiemTra = await thucHienGoiApi(`report?q={"ngayBaoCao": "${cauTruc.ngayBaoCao}"}`);
            if (kiemTra.length > 0) await thucHienGoiApi(`report/${kiemTra[0]._id}`, 'PUT', cauTruc);
            else await thucHienGoiApi('report', 'POST', cauTruc);
            lamMoiThongKeCsdl(capNhatWidgetDb);
        } catch (error) {} finally { setTimeout(() => $('#chi-bao-dang-luu').fadeOut(), 1000); }
    };

    const thucHienTaoBaoCao = (e, chiXem = false) => {
        danhSachNhanVien.sort((a, b) => b.chiTieu - a.chiTieu);
        hienThiDanhSachNhanVien();
        const quanLy = 'TNH';
        const ngayHienThi = dinhDangNgayHienThi(new Date());
        let tMC = 0, tNTB = 0, tETB = 0, nvActive = 0, tPos = 0, tAE = 0;
        let dsChiTiet = [];
        const banDoLichSu = new Map();
        if (baoCaoLichSuGanNhat?.duLieuNvLichSu) baoCaoLichSuGanNhat.duLieuNvLichSu.forEach(n => banDoLichSu.set(n.ten, n));

        danhSachNhanVien.forEach(nv => {
            const bieuTuong = nv.gioiTinh === 'Nữ' ? '👵' : '👨';
            const bc = nv.baoCao;
            let mtd = trichXuatSoLieu(bc, 'MTD MC');
            let ntb = trichXuatSoLieu(bc, 'NTB'), etb = trichXuatSoLieu(bc, 'ETB');
            let mcNay = ntb + etb;
            if (mcNay === 0) mcNay = trichXuatSoLieu(bc, ['Tổng MC', 'MC']);

            if ((nv.trangThai === 'Off' || mcNay === 0) && mtd === 0 && baoCaoLichSuGanNhat) {
                const nvLichSu = banDoLichSu.get(nv.ten);
                mtd = nvLichSu ? (nvLichSu.mtdMC || 0) : 0;
            }

            if (nv.trangThai === 'Off') {
                const matchLyDo = bc.match(/^Fos\s+\S+\s+(.*)$/i);
                const lyDo = (matchLyDo && matchLyDo[1] && matchLyDo[1].toUpperCase() !== 'OFF') ? matchLyDo[1] : 'OFF';
                dsChiTiet.push(`${bieuTuong}${nv.ten}: ${lyDo}/${mtd}/${nv.chiTieu}`);
            } else {
                nvActive++;
                tMC += mcNay; tNTB += ntb; tETB += etb;
                tPos += trichXuatSoLieu(bc, 'Pos'); tAE += trichXuatSoLieu(bc, ['AE+', 'AE Plus']);
                dsChiTiet.push(`${bieuTuong}${nv.ten}: ${mcNay}/${mtd}/${nv.chiTieu}`);
            }
        });

        const nsbqNTB = (nvActive > 0) ? (tNTB / nvActive).toFixed(2) : '0.00';
        const nsbqETB = (nvActive > 0) ? (tETB / nvActive).toFixed(2) : '0.00';
        let ketQua = `${quanLy} ngày ${ngayHienThi}\n🔥${danhSachNhanVien.length} FOS – ${tMC} MC\n✅NTB: ${tNTB}\n✅NSBQ NTB: ${nsbqNTB}\n✅ETB: ${tETB}\n✅NSBQ ETB: ${nsbqETB}\n✅AE+: ${tAE}\n✅Pos: ${tPos}/${danhSachNhanVien.length * 3}\n\n⭐️Active ${nvActive}/${danhSachNhanVien.length}\n${dsChiTiet.join('\n')}`;
        $('#vung-ket-qua-bao-cao').val(ketQua);

        if (!chiXem) {
            const thongKe = { tongFOS: danhSachNhanVien.length, tongMC: tMC, tongNTB: tNTB, nsbqNTB, tongETB: tETB, nsbqETB, tongPosThucHien: tPos, posChiTieu: danhSachNhanVien.length * 3, activeFOS: nvActive, tongAEPlus: tAE };
            luuBaoCaoLenServer(taoCauTrucGuiBaoCao(danhSachNhanVien, baoCaoLichSuGanNhat, thongKe), true);
        }
    };

    // --- HELPER TẠO BÁO CÁO TỪ DB OBJECT ---
    const taiTaoNoiDungBaoCao = (bc) => {
        const ngayHienThi = dinhDangNgayHienThi(bc.ngayBaoCao);
        const thongKe = bc.tongKetToanDoi;
        const dsNv = bc.baoCaoFOS;

        let ketQua = `--- BÁO CÁO LƯU TRỮ NGÀY ${ngayHienThi} ---\n\n`;

        if (thongKe) {
            ketQua += `🔥${thongKe.tongSoFOS} FOS – ${thongKe.tongSoMC} MC\n`;
            ketQua += `✅NTB: ${thongKe.tongSoNTB} (BQ: ${thongKe.NSBQ_NTB})\n`;
            ketQua += `✅ETB: ${thongKe.tongSoETB} (BQ: ${thongKe.NSBQ_ETB})\n`;
            ketQua += `✅AE+: ${thongKe.tongSoAEPlus}\n`;
            ketQua += `✅Pos: ${thongKe.tyLePOS}\n`;
            ketQua += `⭐️Active: ${thongKe.tyLeActiveFOS}\n\n`;
        }

        if (dsNv && dsNv.length > 0) {
            dsNv.forEach(n => {
                 const nvHienTai = danhSachNhanVien.find(nv => nv.ten === n.tenNhanVien);
                 const icon = nvHienTai ? (nvHienTai.gioiTinh === 'Nữ' ? '👵' : '👨') : '👤';

                 const sale = n.chiSoHieuSuat?.saleHomNay || 0;
                 const mtd = n.chiSoHieuSuat?.saleTrongThang || 0;
                 const chiTieu = n.chiSoHieuSuat?.chiTieu || 0;

                 let statusStr = `${sale}/${mtd}/${chiTieu}`;
                 if (n.OFF !== 0 && n.OFF !== '0') {
                     const lyDo = n.OFF === 1 ? 'OFF' : n.OFF;
                     statusStr = `${lyDo}/${mtd}/${chiTieu}`;
                 }

                 ketQua += `${icon}${n.tenNhanVien}: ${statusStr}\n`;
            });
        }
        return ketQua;
    };

    // --- SỰ KIỆN GIAO DIỆN ---
    $('body').on('click', '.lua-chon-giao-dien', function(e) {
        e.preventDefault();
        const theme = $(this).data('theme');
        const mode = $(this).data('mode');
        const lop = `theme-${theme}-${mode}`;
        apDungGiaoDien(lop); 
        luuCauHinhGiaoDien(lop);
        hienThiThongBao(`Giao diện: ${theme} ${mode}`);
    });

    $('#nut-giao-dien-ngau-nhien').on('click', e => { 
        e.preventDefault(); 
        luuCauHinhGiaoDien('random'); 
        apDungGiaoDienNgauNhien(); 
    });

    $('#nut-luu-nv-moi').on('click', async () => {
        const ten = $('#ten-nv-modal').val().trim(), gt = $('#gioi-tinh-nv-modal').val(), ct = parseInt($('#chi-tieu-nv-modal').val()) || 0;
        if (ten && !danhSachNhanVien.some(n => n.ten.toLowerCase() === ten.toLowerCase())) {
            hienThiTaiTrang("Đang lưu nhân viên...");
            try { await thucHienGoiApi('nhanvien', 'POST', { Ten: ten, GioiTinh: gt, ChiTieu: ct }); modalThemNv.hide(); taiDuLieuTuServer(); }
            catch (e) { hienThiThongBao(e.message, 'error'); } finally { anTaiTrang(); }
        }
    });

    $vungDsNv.on('click', '.nut-xoa-nv-kich-hoat', function() {
        nhanVienCanXoa = { id: $(this).data('nv-id'), ten: $(this).data('nv-ten') };
        $('#noi-dung-xac-nhan-xoa').text(`Xoá nhân viên "${nhanVienCanXoa.ten}"?`);
        modalXacNhanXoa.show();
    });

    $('#nut-xac-nhan-xoa-vinh-vien').on('click', async () => {
        if (!nhanVienCanXoa) return;
        hienThiTaiTrang("Đang xoá vĩnh viễn...");
        try { await thucHienGoiApi(`nhanvien/${nhanVienCanXoa.id}`, 'DELETE'); taiDuLieuTuServer(); }
        catch (e) { hienThiThongBao(e.message, 'error'); } finally { anTaiTrang(); modalXacNhanXoa.hide(); }
    });

    $vungDsNv.on('click', '.nut-ten-nv', function() {
        nhanVienHienTai = $(this).data('nv-ten');
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { 
            $('#modalDanBaoCaoLabel').text(`Báo cáo của ${nhanVienHienTai}`); 
            $('#noi-dung-bao-cao-nhap').val(nv.baoCao); 
            modalDanBaoCao.show(); 
        }
    });

    $('#nut-luu-bao-cao-don').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const nd = $('#noi-dung-bao-cao-nhap').val();
            nv.baoCao = nd; nv.trangThai = 'Đã báo cáo'; kiemTraTenTrongBaoCao(nv, nd);
            hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide();
        }
    });

    $('#nut-danh-dau-off').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { nv.baoCao = `Fos ${nv.ten} OFF`; nv.trangThai = 'Off'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide(); }
    });

    $('#nut-xac-nhan-off-co-ly-do').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { nv.baoCao = `Fos ${nv.ten} ${$('#ly-do-off-nhap').val().trim() || 'OFF'}`; nv.trangThai = 'Off'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide(); }
    });

    $vungDsNv.on('click', '.nut-sua-nhanh-nv', function() {
        nhanVienHienTai = $(this).data('nv-ten');
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const bc = nv.baoCao;
            $('#tieu-de-modal-sua-bao-cao').text(`Sửa nhanh: ${nhanVienHienTai}`);
            $('#ntb-sua').val(trichXuatSoLieu(bc, 'NTB')); $('#etb-sua').val(trichXuatSoLieu(bc, 'ETB'));
            $('#pos-sua').val(trichXuatSoLieu(bc, 'Pos')); $('#aeplus-sua').val(trichXuatSoLieu(bc, ['AE+', 'AE Plus']));
            $('#mtd-sua').val(trichXuatSoLieu(bc, 'MTD MC'));
            modalSuaBaoCao.show();
        }
    });

    $('#nut-xac-nhan-sua-bao-cao').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const n = parseInt($('#ntb-sua').val()) || 0, e = parseInt($('#etb-sua').val()) || 0;
            nv.baoCao = `Fos ${nv.ten}\nTổng MC: ${n+e}\nNTB: ${n}\nETB: ${e}\nAE+: ${$('#aeplus-sua').val() || 0}\nPos: ${$('#pos-sua').val() || 0}\nMTD MC: ${$('#mtd-sua').val() || 0}`;
            nv.trangThai = 'Đã báo cáo'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalSuaBaoCao.hide();
        }
    });

    $('#nut-dan-tu-bo-nho').on('click', async () => {
        try { const t = await navigator.clipboard.readText(); if (t) $('#noi-dung-bao-cao-nhap').val(t); } catch(e) {}
    });

    $('#nut-dan-hang-loat').on('click', async () => {
        try { const t = await navigator.clipboard.readText(); if (t) $('#noi-dung-nhieu-bao-cao-nhap').val(t); } catch(e) {}
    });

    $('#nut-xu-ly-nhieu-bao-cao').on('click', () => {
        const vanBan = $('#noi-dung-nhieu-bao-cao-nhap').val().trim();
        if (!vanBan) return;
        const khoiBaoCao = vanBan.split(/(?=^Fos\s)/im); 
        khoiBaoCao.forEach(khoi => {
            const khoiTrim = khoi.trim();
            const nv = danhSachNhanVien.find(n => {
                const tenEscape = n.ten.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
                return new RegExp(`^Fos\\s+${tenEscape}(?=\\s|$)`, 'i').test(khoiTrim);
            });
            if (nv) { nv.baoCao = khoiTrim; nv.trangThai = 'Đã báo cáo'; kiemTraTenTrongBaoCao(nv, khoiTrim); }
        });
        modalDanNhieuBaoCao.hide(); hienThiDanhSachNhanVien(); luuVaoBoNhoTam();
        hienThiThongBao("Đã xử lý xong báo cáo hàng loạt.");
    });

    $('#nut-tao-bao-cao').on('click', () => thucHienTaoBaoCao());
    $('#nut-sao-chep').on('click', function() {
        const $btn = $(this);
        navigator.clipboard.writeText($('#vung-ket-qua-bao-cao').val()).then(() => {
            hienThiThongBao('Đã sao chép báo cáo vào bộ nhớ tạm!');
            $btn.html('<i class="fa-solid fa-check"></i> Đã chép').addClass('btn-success').removeClass('btn-primary');
            setTimeout(() => $btn.html('<i class="fa-regular fa-copy"></i> Sao chép').removeClass('btn-success').addClass('btn-primary'), 2000);
        });
    });

    // --- XỬ LÝ SỰ KIỆN XEM BÁO CÁO CŨ (MỚI) ---
    $('#nut-xem-bao-cao-cu').on('click', async () => {
        hienThiTaiTrang("Đang tải báo cáo cũ...");
        try {
            const homNayStr = dinhDangNgayISO(new Date());
            const truyVan = `q={"ngayBaoCao": {"$lt": "${homNayStr}"}}&h={"$orderby": {"ngayBaoCao": -1}}&max=1`;
            const duLieu = await thucHienGoiApi(`report?${truyVan}`);

            if (duLieu.length > 0) {
                $('#vung-ket-qua-bao-cao-cu').val(taiTaoNoiDungBaoCao(duLieu[0]));
            } else {
                $('#vung-ket-qua-bao-cao-cu').val("Không tìm thấy dữ liệu báo cáo trước ngày hôm nay.");
            }
            modalXemBaoCaoCu.show();
        } catch (e) {
            hienThiThongBao("Lỗi tải lịch sử: " + e.message, "error");
        } finally {
            anTaiTrang();
        }
    });

    // KHỞI CHẠY
    khoiTaoGiaoDien(); 
    xayDungMenuGiaoDien(); 
    taiDuLieuTuServer(); 
});

const DANH_SACH_GIAO_DIEN = {
    'ios18': 'iOS 18 (Apple)',
    'ios26': 'iOS 26 (Futuristic)',
    'oneui': 'OneUI (Samsung)',
    'window11': 'Windows 11 (Microsoft)'
};

export const xayDungMenuGiaoDien = () => {
    const menu = $('#menu-giao-dien-chon');
    if (!menu.length) return;
    menu.empty();
    for (const ma in DANH_SACH_GIAO_DIEN) {
        const ten = DANH_SACH_GIAO_DIEN[ma];
        menu.append(`
            <li class="dropdown-submenu">
                <a class="dropdown-item dropdown-toggle" href="#">${ten}</a>
                <ul class="dropdown-menu">
                    <li><a class="dropdown-item lua-chon-giao-dien" href="#" data-theme="${ma}" data-mode="light">Chế độ Sáng</a></li>
                    <li><a class="dropdown-item lua-chon-giao-dien" href="#" data-theme="${ma}" data-mode="dark">Chế độ Tối</a></li>
                </ul>
            </li>
        `);
    }
};

export const apDungGiaoDien = (tenLopGiaoDien) => {
    const danhSachLop = $('body').attr('class')?.split(' ') || [];
    for (let lop of danhSachLop) {
        if (lop.startsWith('theme-')) {
            $('body').removeClass(lop);
        }
    }
    $('body').addClass(tenLopGiaoDien);
};

export const luuCauHinhGiaoDien = (luaChon) => {
    localStorage.setItem('cau_hinh_giao_dien', luaChon);
};

export const apDungGiaoDienNgauNhien = () => {
    const danhSachMa = Object.keys(DANH_SACH_GIAO_DIEN);
    const maNgauNhien = danhSachMa[Math.floor(Math.random() * danhSachMa.length)];
    const cheDoNgauNhien = Math.random() < 0.5 ? 'light' : 'dark';
    const lopGiaoDienNgauNhien = `theme-${maNgauNhien}-${cheDoNgauNhien}`;
    apDungGiaoDien(lopGiaoDienNgauNhien);
};

export const khoiTaoGiaoDien = () => {
    const cauHinhCu = localStorage.getItem('cau_hinh_giao_dien') || 'theme-ios18-light';
    if (cauHinhCu === 'random') {
        apDungGiaoDienNgauNhien();
    } else {
        apDungGiaoDien(cauHinhCu);
    }
};

/* --- HỆ THỐNG GIAO DIỆN SỬ DỤNG BIẾN CSS --- */

:root {
    /* Mặc định (Fallback) */
    --bg-gradient: #f2f2f7;
    --bg-image: none;
    --card-bg: rgba(255, 255, 255, 0.7);
    --text-primary: #000000;
    --text-secondary: #3C3C4399; /* System Gray 2 */
    --main-title-color: #000000;
    --accent-blue: #007AFF;
    --accent-green: #34C759;
    --accent-red: #FF3B30;
    --accent-gray: #8E8E93;
    --input-bg: rgba(118, 118, 128, 0.12);
    --input-border: rgba(0, 0, 0, 0);
    --btn-fos-bg: rgba(255, 255, 255, 1);
    --btn-fos-border: rgba(0, 0, 0, 0);
    --card-radius: 18px;
    --btn-radius: 12px;
    --backdrop-blur: 20px;
    --shadow-soft: 0 4px 24px rgba(0,0,0,0.06);
}

/* --- 1. iOS 18 (Apple Design Resources) --- */
body.theme-ios18-light {
    --bg-gradient: #F2F2F7; /* System Grouped Background */
    --card-bg: rgba(255, 255, 255, 0.85);
    --text-primary: #000000;
    --text-secondary: rgba(60, 60, 67, 0.6);
    --accent-blue: #007AFF;
    --input-bg: rgba(118, 118, 128, 0.12);
    --btn-fos-bg: #FFFFFF;
    --card-radius: 20px;
    --backdrop-blur: 30px;
}

body.theme-ios18-dark {
    --bg-gradient: #000000; /* True Black */
    --card-bg: rgba(28, 28, 30, 0.85); /* System Gray 6 */
    --text-primary: #FFFFFF;
    --text-secondary: rgba(235, 235, 245, 0.6);
    --accent-blue: #0A84FF;
    --input-bg: rgba(118, 118, 128, 0.24);
    --btn-fos-bg: #1C1C1E; /* System Gray 5 */
    --btn-fos-border: rgba(255, 255, 255, 0.05);
    --card-radius: 20px;
    --backdrop-blur: 30px;
}

/* --- 2. OneUI (Samsung Design) --- */
body.theme-oneui-light {
    --bg-gradient: #F7F7F7;
    --card-bg: #FFFFFF; /* OneUI Cards are solid usually */
    --text-primary: #000000;
    --text-secondary: #585858;
    --accent-blue: #0072DE; /* Samsung Blue */
    --input-bg: #F0F0F0;
    --btn-fos-bg: #FFFFFF;
    --btn-fos-border: #E0E0E0;
    --card-radius: 26px; /* Super rounded */
    --btn-radius: 24px;
    --backdrop-blur: 0px; /* OneUI uses less glass, more solid */
    --shadow-soft: 0 2px 10px rgba(0,0,0,0.03);
}

body.theme-oneui-dark {
    --bg-gradient: #000000; /* AMOLED Black */
    --card-bg: #1E1E1E; /* Dark Gray Cards */
    --text-primary: #FFFFFF;
    --text-secondary: #999999;
    --accent-blue: #3E91FF;
    --input-bg: #2C2C2C;
    --btn-fos-bg: #252525;
    --btn-fos-border: transparent;
    --card-radius: 26px;
    --btn-radius: 24px;
    --backdrop-blur: 0px;
}

/* --- 3. Windows 11 (Fluent Design) --- */
body.theme-window11-light {
    /* Mica Effect Simulation */
    --bg-gradient: linear-gradient(135deg, #F3F3F3 0%, #E8F2FC 100%); 
    --card-bg: rgba(255, 255, 255, 0.75);
    --text-primary: #1A1A1A;
    --text-secondary: #5D5D5D;
    --accent-blue: #0067C0;
    --input-bg: rgba(255, 255, 255, 0.7);
    --input-border: rgba(0, 0, 0, 0.06);
    --btn-fos-bg: rgba(255, 255, 255, 0.8);
    --btn-fos-border: rgba(0, 0, 0, 0.06);
    --card-radius: 8px; /* Distinctive small radius */
    --btn-radius: 6px;
    --backdrop-blur: 20px; /* Acrylic */
    --shadow-soft: 0 4px 12px rgba(0,0,0,0.08);
}

body.theme-window11-dark {
    --bg-gradient: linear-gradient(135deg, #202020 0%, #1A1A1A 100%);
    --card-bg: rgba(32, 32, 32, 0.85); /* Acrylic Dark */
    --text-primary: #FFFFFF;
    --text-secondary: #A0A0A0;
    --accent-blue: #4CC2FF;
    --input-bg: rgba(255, 255, 255, 0.05);
    --input-border: rgba(255, 255, 255, 0.08);
    --btn-fos-bg: rgba(255, 255, 255, 0.06);
    --btn-fos-border: rgba(255, 255, 255, 0.05);
    --card-radius: 8px;
    --btn-radius: 6px;
    --backdrop-blur: 25px;
}

/* --- 4. iOS 26 (Futuristic Concept) --- */
body.theme-ios26-light {
    /* Titanium / Holographic Feel */
    --bg-gradient: radial-gradient(circle at top left, #eef2f3, #d9e4f5, #eef2f3);
    --card-bg: rgba(255, 255, 255, 0.45); /* Hyper Glass */
    --text-primary: #1d1d1f;
    --text-secondary: rgba(29, 29, 31, 0.6);
    --accent-blue: #00C7BE; /* Cyan/Teal futuristic accent */
    --input-bg: rgba(255, 255, 255, 0.4);
    --btn-fos-bg: rgba(255, 255, 255, 0.3);
    --btn-fos-border: rgba(255, 255, 255, 0.6);
    --card-radius: 32px; /* Ultra smooth */
    --btn-radius: 16px;
    --backdrop-blur: 50px;
    --shadow-soft: 0 10px 40px rgba(0, 199, 190, 0.15); /* Colored shadow */
}

body.theme-ios26-dark {
    /* Deep Space */
    --bg-gradient: radial-gradient(circle at bottom right, #2b1055, #000000);
    --card-bg: rgba(30, 30, 40, 0.35);
    --text-primary: #FFFFFF;
    --text-secondary: rgba(255, 255, 255, 0.5);
    --accent-blue: #D65DB1; /* Neon Violet/Pink */
    --input-bg: rgba(255, 255, 255, 0.1);
    --btn-fos-bg: rgba(255, 255, 255, 0.05);
    --btn-fos-border: rgba(255, 255, 255, 0.15);
    --card-radius: 32px;
    --btn-radius: 16px;
    --backdrop-blur: 60px;
    --shadow-soft: 0 10px 40px rgba(214, 93, 177, 0.2);
}


/* --- BASE UI STYLES --- */

#lop-phu-tai-trang {
    position: fixed; top: 0; left: 0; width: 100%; height: 100%;
    background: rgba(0, 0, 0, 0.7); backdrop-filter: blur(10px);
    display: none; flex-direction: column; justify-content: center; align-items: center;
    z-index: 9999; color: white;
}

body {
    font-family: 'Poppins', sans-serif;
    background: var(--bg-gradient);
    background-size: cover; background-attachment: fixed;
    color: var(--text-primary);
    transition: background 0.5s ease, color 0.3s ease;
    min-height: 100vh;
}

/* Settings Button */
.settings-container { position: fixed; top: 25px; right: 25px; z-index: 1100; }

#nut-cai-dat {
    cursor: pointer; font-size: 1.5rem; color: var(--accent-blue);
    background: var(--card-bg); width: 50px; height: 50px;
    display: flex; align-items: center; justify-content: center;
    border-radius: 50%;
    box-shadow: var(--shadow-soft);
    transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275), background 0.3s ease;
    backdrop-filter: blur(var(--backdrop-blur));
    border: 1px solid rgba(255, 255, 255, 0.1);
    -webkit-backdrop-filter: blur(var(--backdrop-blur));
}
#nut-cai-dat:hover { transform: rotate(90deg) scale(1.1); }

/* Dropdowns */
.dropdown-menu {
    border-radius: var(--btn-radius);
    padding: 0.5rem;
    border: 1px solid rgba(128, 128, 128, 0.1);
    background: var(--card-bg);
    backdrop-filter: blur(var(--backdrop-blur));
    -webkit-backdrop-filter: blur(var(--backdrop-blur));
    box-shadow: var(--shadow-soft) !important;
}

.dropdown-item {
    border-radius: calc(var(--btn-radius) - 4px);
    color: var(--text-primary);
    font-size: 0.9rem;
}
.dropdown-item:hover {
    background-color: var(--accent-blue);
    color: #fff !important;
}
.dropdown-item:hover i { color: #fff !important; }

/* Submenu Fix */
.dropdown-submenu { position: relative; }
.dropdown-submenu > .dropdown-menu {
    top: 0; left: auto; right: 100%;
    margin-top: -5px; margin-right: 0px; display: none;
}
.dropdown-submenu:hover > .dropdown-menu { display: block; }
.dropdown-submenu:hover > .dropdown-menu::before {
    content: ""; position: absolute; top: 0; right: -20px;
    width: 25px; height: 100%; background: transparent; z-index: -1;
}

/* Layout Elements */
.main-title { font-weight: 700; color: var(--main-title-color); letter-spacing: -0.5px; }

.card, .modal-content, .glass-card {
    background: var(--card-bg);
    backdrop-filter: blur(var(--backdrop-blur));
    -webkit-backdrop-filter: blur(var(--backdrop-blur));
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: var(--card-radius);
    box-shadow: var(--shadow-soft);
}

.modal-header { border-bottom: 1px solid rgba(128, 128, 128, 0.1); }
.modal-footer { border-top: 1px solid rgba(128, 128, 128, 0.1); }

/* Form Controls */
.form-control, .form-select {
    background-color: var(--input-bg);
    border: 1px solid var(--input-border);
    color: var(--text-primary);
    border-radius: var(--btn-radius);
}
.form-control:focus, .form-select:focus {
    background-color: var(--input-bg);
    color: var(--text-primary);
    border-color: var(--accent-blue);
    box-shadow: 0 0 0 0.25rem rgba(0, 122, 255, 0.25);
}

/* Buttons */
.btn { border-radius: var(--btn-radius); font-weight: 500; }
.btn-primary { background-color: var(--accent-blue); border-color: var(--accent-blue); }
.btn-primary:hover { opacity: 0.9; }

/* Employee List */
#vung-danh-sach-nv {
    max-height: 420px; overflow-y: auto;
    padding: 12px; margin-bottom: 20px;
    border-radius: var(--card-radius);
    background: rgba(0,0,0,0.03);
}

.nut-ten-nv {
    background-color: var(--btn-fos-bg);
    border: 1px solid var(--btn-fos-border);
    color: var(--text-primary);
    flex: 1; text-align: left; font-weight: 600;
    border-radius: var(--btn-radius) 0 0 var(--btn-radius) !important;
    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    padding: 10px 15px;
    transition: all 0.2s;
}
.nut-ten-nv:hover { opacity: 0.8; }
.nut-ten-nv.da-bao-cao { background-color: var(--accent-green) !important; color: white !important; border-color: var(--accent-green); }
.nut-ten-nv.nghi { background-color: var(--accent-gray) !important; color: white !important; text-decoration: line-through; opacity: 0.8; }
.nut-ten-nv.sai-ten { background-color: var(--accent-red) !important; color: white !important; }

.nut-sua-nv { background-color: var(--accent-blue); color: white; width: 44px; border: none; }
.nut-xoa-nv { background-color: var(--accent-red); color: white; border-radius: 0 var(--btn-radius) var(--btn-radius) 0 !important; width: 44px; border: none; }

#chi-bao-dang-luu {
    position: fixed; bottom: 75px; right: 20px;
    z-index: 2000; background: var(--accent-blue); padding: 12px 24px;
    border-radius: 50px; box-shadow: 0 10px 25px rgba(0,122,255,0.3);
    display: none; align-items: center; gap: 10px; color: white;
    font-size: 0.9rem; font-weight: 500;
}

/* System Monitor */
#system-monitor-panel.show { opacity: 1 !important; transform: scale(1) translateY(0) !important; display: block !important; }
.status-dot { height: 8px; width: 8px; border-radius: 50%; display: inline-block; margin-right: 0; }
.status-dot.online { background-color: var(--accent-green); box-shadow: 0 0 8px var(--accent-green); }
.status-dot.offline { background-color: var(--accent-red); }

/* Scrollbar */
::-webkit-scrollbar { width: 8px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--accent-gray); border-radius: 10px; opacity: 0.5; }
::-webkit-scrollbar-thumb:hover { background: var(--text-secondary); }

import { KHOA_BO_NHO_TAM_CUC_BO } from './config.js';
import { hienThiThongBao, hienThiTaiTrang, anTaiTrang, dinhDangNgayHienThi, dinhDangNgayISO, trichXuatSoLieu } from './utils.js';
import { khoiTaoGiaoDien, xayDungMenuGiaoDien, apDungGiaoDien, luuCauHinhGiaoDien, apDungGiaoDienNgauNhien } from './theme.js';
import { thucHienGoiApi, ghiNhanTuongTacApi, lamMoiThongKeCsdl, datCheDoUngDung, layCheDoUngDung } from './api.js';
import { kiemTraTenTrongBaoCao, taoCauTrucGuiBaoCao } from './report.js';

$(function() {
    // --- TRẠNG THÁI ỨNG DỤNG ---
    let danhSachNhanVien = []; 
    let baoCaoLichSuGanNhat = null; 
    let ngayBaoCaoLichSu = null; 
    let nhanVienHienTai = null;
    let nhanVienCanXoa = null;

    // --- KHỞI TẠO MODAL BOOTSTRAP ---
    const modalThemNv = new bootstrap.Modal('#modal-them-nhan-vien');
    const modalDanBaoCao = new bootstrap.Modal('#modal-dan-bao-cao');
    const modalSuaBaoCao = new bootstrap.Modal('#modal-sua-bao-cao');
    const modalDanNhieuBaoCao = new bootstrap.Modal('#modal-dan-nhieu-bao-cao');
    const modalXacNhanXoa = new bootstrap.Modal('#modal-xac-nhan-xoa');
    const modalXemBaoCaoCu = new bootstrap.Modal('#modal-xem-bao-cao-cu');

    // --- CẬP NHẬT THÔNG TIN BUILD ---
    const phienBanBuild = "v1.6.0-beta";
    const thoiGianBuildStr = "2026.01.06 17:15"; 
    $('#thoi-gian-build').text(thoiGianBuildStr);
    $('.build-version').text(phienBanBuild);

    // --- SYSTEM MONITOR WIDGET ---
    $('#btn-toggle-monitor').on('click', function() {
        const $panel = $('#system-monitor-panel');
        if ($panel.hasClass('show')) {
            $panel.removeClass('show');
            setTimeout(() => $panel.hide(), 300); // Wait for transition
        } else {
            $panel.show();
            // Small delay to allow display:block to apply before transition
            setTimeout(() => $panel.addClass('show'), 10);
        }
    });

    const capNhatWidgetDb = (trucTuyen, slNv, slBaoCao, slTruyCap) => {
        const $cham = $('#cham-trang-thai-db');
        const $chu = $('#chu-trang-thai-db');
        const $nv = $('#so-luong-nv-db');
        const $bc = $('#so-luong-bao-cao-db');
        const $luong = $('#luong-truy-cap-api');

        if (trucTuyen) {
            $cham.removeClass('offline').addClass('online');
            $chu.text('Online');
        } else {
            $cham.removeClass('online').addClass('offline');
            $chu.text('Offline');
        }
        if (slNv !== null) $nv.text(`${slNv} NV`);
        if (slBaoCao !== null) $bc.text(`${slBaoCao} Rpt`);
        if (slTruyCap !== null) $luong.text(`${slTruyCap}`);
    }

    const $vungDsNv = $('#vung-danh-sach-nv');

    const capNhatNutTaoBaoCao = () => {
        const daBaoCao = danhSachNhanVien.filter(nv => nv.trangThai !== 'Chưa báo cáo').length;
        const tongSo = danhSachNhanVien.length;
        $('#nut-tao-bao-cao').html(`Tạo & Lưu Báo Cáo (${daBaoCao}/${tongSo})`);
    };

    const hienThiDanhSachNhanVien = () => {
        if (danhSachNhanVien.length === 0) {
             $vungDsNv.html('<div class="text-center py-3 text-muted">Danh sách trống.</div>');
             capNhatNutTaoBaoCao();
             return;
        }

        let html = '<div class="row g-2">';
        danhSachNhanVien.forEach(nv => {
            let lopNut = 'nut-ten-nv btn';
            if (nv.kiemTraTen === false) lopNut += ' sai-ten';
            else if (nv.trangThai === 'Đã báo cáo') lopNut += ' da-bao-cao';
            else if (nv.trangThai === 'Off') lopNut += ' nghi';

            html += `
                <div class="col-6">
                    <div class="input-group shadow-sm" style="border-radius: var(--btn-radius); overflow: hidden;">
                        <button class="${lopNut}" data-nv-ten="${nv.ten}" title="${nv.ten}">
                            ${nv.ten}
                        </button>
                        <button class="btn nut-sua-nv nut-sua-nhanh-nv" data-nv-ten="${nv.ten}">
                            <i class="fa-solid fa-pen-to-square"></i>
                        </button>
                        <button class="btn nut-xoa-nv nut-xoa-nv-kich-hoat" data-nv-id="${nv._id}" data-nv-ten="${nv.ten}">
                            <i class="fa-solid fa-trash-can"></i>
                        </button>
                    </div>
                </div>
            `;
        });
        html += '</div>';
        $vungDsNv.html(html);
        capNhatNutTaoBaoCao();
    };

    const luuVaoBoNhoTam = () => {
        const homNayStr = dinhDangNgayISO(new Date());
        const duLieu = {
            ngay: homNayStr,
            duLieuNv: danhSachNhanVien.map(n => ({
                _id: n._id, baoCao: n.baoCao, trangThai: n.trangThai, kiemTraTen: n.kiemTraTen
            })),
            vanBanKetQua: $('#vung-ket-qua-bao-cao').val()
        };
        localStorage.setItem(KHOA_BO_NHO_TAM_CUC_BO, JSON.stringify(duLieu));
    };

    const khoiPhuTuBoNhoTam = () => {
        const duLieuTho = localStorage.getItem(KHOA_BO_NHO_TAM_CUC_BO);
        if (!duLieuTho) return false;
        try {
            const duLieu = JSON.parse(duLieuTho);
            if (duLieu.ngay !== dinhDangNgayISO(new Date())) {
                localStorage.removeItem(KHOA_BO_NHO_TAM_CUC_BO);
                return false;
            }
            duLieu.duLieuNv.forEach(itemTam => {
                const nv = danhSachNhanVien.find(n => n._id === itemTam._id);
                if (nv && itemTam.baoCao) {
                    nv.baoCao = itemTam.baoCao; 
                    nv.trangThai = itemTam.trangThai; 
                    nv.kiemTraTen = itemTam.kiemTraTen;
                }
            });
            hienThiDanhSachNhanVien();
            if(duLieu.vanBanKetQua) $('#vung-ket-qua-bao-cao').val(duLieu.vanBanKetQua);
            return true;
        } catch (e) { return false; }
    };

    const taiDuLieuTuServer = async () => {
        hienThiTaiTrang("Đang tải danh sách FOS...");
        try {
            ghiNhanTuongTacApi().catch(() => {});

            const duLieuGoc = await thucHienGoiApi('nhanvien?h={"$orderby": {"Ten": 1}}');
            datCheDoUngDung('online');
            danhSachNhanVien = duLieuGoc.map(item => ({
                _id: item._id, ten: item.Ten, gioiTinh: item.GioiTinh,
                chiTieu: parseInt(item.ChiTieu, 10) || 50, baoCao: '',
                trangThai: 'Chưa báo cáo', kiemTraTen: null
            }));

            hienThiDanhSachNhanVien();

            // Ẩn loader ngay khi danh sách nhân viên hiện ra để user thao tác ngay
            anTaiTrang(); 

            // Các công việc nền tiếp tục chạy ngầm sau khi user đã có thể thao tác
            khoiPhuTuBoNhoTam();
            lamMoiThongKeCsdl(capNhatWidgetDb).catch(() => {});
            khoiPhuPhienLamViec().catch(() => {});

        } catch (error) {
            datCheDoUngDung('offline');
            hienThiThongBao("Đang hoạt động ngoại tuyến", "info");
            try {
                const phanHoi = await fetch('fos.txt');
                const text = await phanHoi.text();
                danhSachNhanVien = text.split('\n').filter(l => l.trim()).map((line, index) => {
                    const parts = line.split('|');
                    return {
                        _id: `local_${index}`, ten: parts[0]?.trim(), gioiTinh: parts[1]?.trim(), 
                        chiTieu: parseInt(parts[2]?.trim() || '50'), baoCao: '', 
                        trangThai: 'Chưa báo cáo', kiemTraTen: null
                    };
                });
                hienThiDanhSachNhanVien();
                anTaiTrang();
                khoiPhuTuBoNhoTam();
            } catch (e) {
                anTaiTrang();
            }
        }
    };

    const khoiPhuPhienLamViec = async () => {
        const homNayStr = dinhDangNgayISO(new Date());

        try {
            const bcHomNay = await thucHienGoiApi(`report?q={"ngayBaoCao": "${homNayStr}"}`);
            if (bcHomNay.length > 0) {
                bcHomNay[0].baoCaoFOS.forEach(item => {
                    const nv = danhSachNhanVien.find(n => n.ten === item.tenNhanVien);
                    if (nv && nv.baoCao === '') {
                        nv.trangThai = (item.OFF === 0 || item.OFF === '0') ? 'Đã báo cáo' : 'Off';
                        nv.baoCao = item.rawReport || `Fos ${item.tenNhanVien} ${nv.trangThai === 'Off' ? 'OFF' : ''}`;
                    }
                });
                hienThiDanhSachNhanVien();
            }
        } catch (e) {}

        // Lấy mốc lịch sử thực sự cũ hơn hôm nay
        try {
            const truyVanLichSu = `{"ngayBaoCao": {"$lt": "${homNayStr}"}}`;
            const sapXepLichSu = `{"$orderby": {"ngayBaoCao": -1}}`;
            const dsBcCu = await thucHienGoiApi(`report?q=${truyVanLichSu}&h=${sapXepLichSu}&max=1`);

            if (dsBcCu.length > 0) {
                const bcLichSu = dsBcCu[0];
                baoCaoLichSuGanNhat = bcLichSu;
                ngayBaoCaoLichSu = bcLichSu.ngayBaoCao;
                baoCaoLichSuGanNhat.duLieuNvLichSu = bcLichSu.baoCaoFOS.map(item => ({
                    ten: item.tenNhanVien, 
                    mtdMC: item.chiSoHieuSuat.saleTrongThang
                }));
                thucHienTaoBaoCao(null, true);
            }
        } catch (e) {}
    };

    const luuBaoCaoLenServer = async (cauTruc, chayNgam = false) => {
        if (layCheDoUngDung() === 'offline') return;
        if (chayNgam) $('#chi-bao-dang-luu').css('display', 'flex');
        try {
            const kiemTra = await thucHienGoiApi(`report?q={"ngayBaoCao": "${cauTruc.ngayBaoCao}"}`);
            if (kiemTra.length > 0) await thucHienGoiApi(`report/${kiemTra[0]._id}`, 'PUT', cauTruc);
            else await thucHienGoiApi('report', 'POST', cauTruc);
            lamMoiThongKeCsdl(capNhatWidgetDb);
        } catch (error) {} finally { setTimeout(() => $('#chi-bao-dang-luu').fadeOut(), 1000); }
    };

    const thucHienTaoBaoCao = (e, chiXem = false) => {
        danhSachNhanVien.sort((a, b) => b.chiTieu - a.chiTieu);
        hienThiDanhSachNhanVien();
        const quanLy = 'TNH';
        const ngayHienThi = dinhDangNgayHienThi(new Date());
        let tMC = 0, tNTB = 0, tETB = 0, nvActive = 0, tPos = 0, tAE = 0;
        let dsChiTiet = [];
        const banDoLichSu = new Map();
        if (baoCaoLichSuGanNhat?.duLieuNvLichSu) baoCaoLichSuGanNhat.duLieuNvLichSu.forEach(n => banDoLichSu.set(n.ten, n));

        danhSachNhanVien.forEach(nv => {
            const bieuTuong = nv.gioiTinh === 'Nữ' ? '👵' : '👨';
            const bc = nv.baoCao;
            let mtd = trichXuatSoLieu(bc, 'MTD MC');
            let ntb = trichXuatSoLieu(bc, 'NTB'), etb = trichXuatSoLieu(bc, 'ETB');
            let mcNay = ntb + etb;
            if (mcNay === 0) mcNay = trichXuatSoLieu(bc, ['Tổng MC', 'MC']);

            if ((nv.trangThai === 'Off' || mcNay === 0) && mtd === 0 && baoCaoLichSuGanNhat) {
                const nvLichSu = banDoLichSu.get(nv.ten);
                mtd = nvLichSu ? (nvLichSu.mtdMC || 0) : 0;
            }

            if (nv.trangThai === 'Off') {
                const matchLyDo = bc.match(/^Fos\s+\S+\s+(.*)$/i);
                const lyDo = (matchLyDo && matchLyDo[1] && matchLyDo[1].toUpperCase() !== 'OFF') ? matchLyDo[1] : 'OFF';
                dsChiTiet.push(`${bieuTuong}${nv.ten}: ${lyDo}/${mtd}/${nv.chiTieu}`);
            } else {
                nvActive++;
                tMC += mcNay; tNTB += ntb; tETB += etb;
                tPos += trichXuatSoLieu(bc, 'Pos'); tAE += trichXuatSoLieu(bc, ['AE+', 'AE Plus']);
                dsChiTiet.push(`${bieuTuong}${nv.ten}: ${mcNay}/${mtd}/${nv.chiTieu}`);
            }
        });

        const nsbqNTB = (nvActive > 0) ? (tNTB / nvActive).toFixed(2) : '0.00';
        const nsbqETB = (nvActive > 0) ? (tETB / nvActive).toFixed(2) : '0.00';
        let ketQua = `${quanLy} ngày ${ngayHienThi}\n🔥${danhSachNhanVien.length} FOS – ${tMC} MC\n✅NTB: ${tNTB}\n✅NSBQ NTB: ${nsbqNTB}\n✅ETB: ${tETB}\n✅NSBQ ETB: ${nsbqETB}\n✅AE+: ${tAE}\n✅Pos: ${tPos}/${danhSachNhanVien.length * 3}\n\n⭐️Active ${nvActive}/${danhSachNhanVien.length}\n${dsChiTiet.join('\n')}`;
        $('#vung-ket-qua-bao-cao').val(ketQua);

        if (!chiXem) {
            const thongKe = { tongFOS: danhSachNhanVien.length, tongMC: tMC, tongNTB: tNTB, nsbqNTB, tongETB: tETB, nsbqETB, tongPosThucHien: tPos, posChiTieu: danhSachNhanVien.length * 3, activeFOS: nvActive, tongAEPlus: tAE };
            luuBaoCaoLenServer(taoCauTrucGuiBaoCao(danhSachNhanVien, baoCaoLichSuGanNhat, thongKe), true);
        }
    };

    // --- HELPER TẠO BÁO CÁO TỪ DB OBJECT ---
    const taiTaoNoiDungBaoCao = (bc) => {
        const ngayHienThi = dinhDangNgayHienThi(bc.ngayBaoCao);
        const thongKe = bc.tongKetToanDoi;
        const dsNv = bc.baoCaoFOS;

        let ketQua = `--- BÁO CÁO LƯU TRỮ NGÀY ${ngayHienThi} ---\n\n`;

        if (thongKe) {
            ketQua += `🔥${thongKe.tongSoFOS} FOS – ${thongKe.tongSoMC} MC\n`;
            ketQua += `✅NTB: ${thongKe.tongSoNTB} (BQ: ${thongKe.NSBQ_NTB})\n`;
            ketQua += `✅ETB: ${thongKe.tongSoETB} (BQ: ${thongKe.NSBQ_ETB})\n`;
            ketQua += `✅AE+: ${thongKe.tongSoAEPlus}\n`;
            ketQua += `✅Pos: ${thongKe.tyLePOS}\n`;
            ketQua += `⭐️Active: ${thongKe.tyLeActiveFOS}\n\n`;
        }

        if (dsNv && dsNv.length > 0) {
            dsNv.forEach(n => {
                 const nvHienTai = danhSachNhanVien.find(nv => nv.ten === n.tenNhanVien);
                 const icon = nvHienTai ? (nvHienTai.gioiTinh === 'Nữ' ? '👵' : '👨') : '👤';

                 const sale = n.chiSoHieuSuat?.saleHomNay || 0;
                 const mtd = n.chiSoHieuSuat?.saleTrongThang || 0;
                 const chiTieu = n.chiSoHieuSuat?.chiTieu || 0;

                 let statusStr = `${sale}/${mtd}/${chiTieu}`;
                 if (n.OFF !== 0 && n.OFF !== '0') {
                     const lyDo = n.OFF === 1 ? 'OFF' : n.OFF;
                     statusStr = `${lyDo}/${mtd}/${chiTieu}`;
                 }

                 ketQua += `${icon}${n.tenNhanVien}: ${statusStr}\n`;
            });
        }
        return ketQua;
    };

    // --- SỰ KIỆN GIAO DIỆN ---
    $('body').on('click', '.lua-chon-giao-dien', function(e) {
        e.preventDefault();
        const theme = $(this).data('theme');
        const mode = $(this).data('mode');
        const lop = `theme-${theme}-${mode}`;
        apDungGiaoDien(lop); 
        luuCauHinhGiaoDien(lop);
        hienThiThongBao(`Giao diện: ${theme} ${mode}`);
    });

    $('#nut-giao-dien-ngau-nhien').on('click', e => { 
        e.preventDefault(); 
        luuCauHinhGiaoDien('random'); 
        apDungGiaoDienNgauNhien(); 
    });

    $('#nut-luu-nv-moi').on('click', async () => {
        const ten = $('#ten-nv-modal').val().trim(), gt = $('#gioi-tinh-nv-modal').val(), ct = parseInt($('#chi-tieu-nv-modal').val()) || 0;
        if (ten && !danhSachNhanVien.some(n => n.ten.toLowerCase() === ten.toLowerCase())) {
            hienThiTaiTrang("Đang lưu nhân viên...");
            try { await thucHienGoiApi('nhanvien', 'POST', { Ten: ten, GioiTinh: gt, ChiTieu: ct }); modalThemNv.hide(); taiDuLieuTuServer(); }
            catch (e) { hienThiThongBao(e.message, 'error'); } finally { anTaiTrang(); }
        }
    });

    $vungDsNv.on('click', '.nut-xoa-nv-kich-hoat', function() {
        nhanVienCanXoa = { id: $(this).data('nv-id'), ten: $(this).data('nv-ten') };
        $('#noi-dung-xac-nhan-xoa').text(`Xoá nhân viên "${nhanVienCanXoa.ten}"?`);
        modalXacNhanXoa.show();
    });

    $('#nut-xac-nhan-xoa-vinh-vien').on('click', async () => {
        if (!nhanVienCanXoa) return;
        hienThiTaiTrang("Đang xoá vĩnh viễn...");
        try { await thucHienGoiApi(`nhanvien/${nhanVienCanXoa.id}`, 'DELETE'); taiDuLieuTuServer(); }
        catch (e) { hienThiThongBao(e.message, 'error'); } finally { anTaiTrang(); modalXacNhanXoa.hide(); }
    });

    $vungDsNv.on('click', '.nut-ten-nv', function() {
        nhanVienHienTai = $(this).data('nv-ten');
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { 
            $('#modalDanBaoCaoLabel').text(`Báo cáo của ${nhanVienHienTai}`); 
            $('#noi-dung-bao-cao-nhap').val(nv.baoCao); 
            modalDanBaoCao.show(); 
        }
    });

    $('#nut-luu-bao-cao-don').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const nd = $('#noi-dung-bao-cao-nhap').val();
            nv.baoCao = nd; nv.trangThai = 'Đã báo cáo'; kiemTraTenTrongBaoCao(nv, nd);
            hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide();
        }
    });

    $('#nut-danh-dau-off').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { nv.baoCao = `Fos ${nv.ten} OFF`; nv.trangThai = 'Off'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide(); }
    });

    $('#nut-xac-nhan-off-co-ly-do').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { nv.baoCao = `Fos ${nv.ten} ${$('#ly-do-off-nhap').val().trim() || 'OFF'}`; nv.trangThai = 'Off'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide(); }
    });

    $vungDsNv.on('click', '.nut-sua-nhanh-nv', function() {
        nhanVienHienTai = $(this).data('nv-ten');
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const bc = nv.baoCao;
            $('#tieu-de-modal-sua-bao-cao').text(`Sửa nhanh: ${nhanVienHienTai}`);
            $('#ntb-sua').val(trichXuatSoLieu(bc, 'NTB')); $('#etb-sua').val(trichXuatSoLieu(bc, 'ETB'));
            $('#pos-sua').val(trichXuatSoLieu(bc, 'Pos')); $('#aeplus-sua').val(trichXuatSoLieu(bc, ['AE+', 'AE Plus']));
            $('#mtd-sua').val(trichXuatSoLieu(bc, 'MTD MC'));
            modalSuaBaoCao.show();
        }
    });

    $('#nut-xac-nhan-sua-bao-cao').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const n = parseInt($('#ntb-sua').val()) || 0, e = parseInt($('#etb-sua').val()) || 0;
            nv.baoCao = `Fos ${nv.ten}\nTổng MC: ${n+e}\nNTB: ${n}\nETB: ${e}\nAE+: ${$('#aeplus-sua').val() || 0}\nPos: ${$('#pos-sua').val() || 0}\nMTD MC: ${$('#mtd-sua').val() || 0}`;
            nv.trangThai = 'Đã báo cáo'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalSuaBaoCao.hide();
        }
    });

    $('#nut-dan-tu-bo-nho').on('click', async () => {
        try { const t = await navigator.clipboard.readText(); if (t) $('#noi-dung-bao-cao-nhap').val(t); } catch(e) {}
    });

    $('#nut-dan-hang-loat').on('click', async () => {
        try { const t = await navigator.clipboard.readText(); if (t) $('#noi-dung-nhieu-bao-cao-nhap').val(t); } catch(e) {}
    });

    $('#nut-xu-ly-nhieu-bao-cao').on('click', () => {
        const vanBan = $('#noi-dung-nhieu-bao-cao-nhap').val().trim();
        if (!vanBan) return;
        const khoiBaoCao = vanBan.split(/(?=^Fos\s)/im); 
        khoiBaoCao.forEach(khoi => {
            const khoiTrim = khoi.trim();
            const nv = danhSachNhanVien.find(n => {
                const tenEscape = n.ten.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
                return new RegExp(`^Fos\\s+${tenEscape}(?=\\s|$)`, 'i').test(khoiTrim);
            });
            if (nv) { nv.baoCao = khoiTrim; nv.trangThai = 'Đã báo cáo'; kiemTraTenTrongBaoCao(nv, khoiTrim); }
        });
        modalDanNhieuBaoCao.hide(); hienThiDanhSachNhanVien(); luuVaoBoNhoTam();
        hienThiThongBao("Đã xử lý xong báo cáo hàng loạt.");
    });

    $('#nut-tao-bao-cao').on('click', () => thucHienTaoBaoCao());
    $('#nut-sao-chep').on('click', function() {
        const $btn = $(this);
        navigator.clipboard.writeText($('#vung-ket-qua-bao-cao').val()).then(() => {
            hienThiThongBao('Đã sao chép báo cáo vào bộ nhớ tạm!');
            $btn.html('<i class="fa-solid fa-check"></i> Đã chép').addClass('btn-success').removeClass('btn-primary');
            setTimeout(() => $btn.html('<i class="fa-regular fa-copy"></i> Sao chép').removeClass('btn-success').addClass('btn-primary'), 2000);
        });
    });

    // --- XỬ LÝ SỰ KIỆN XEM BÁO CÁO CŨ (MỚI) ---
    $('#nut-xem-bao-cao-cu').on('click', async () => {
        hienThiTaiTrang("Đang tải báo cáo cũ...");
        try {
            const homNayStr = dinhDangNgayISO(new Date());
            const truyVan = `q={"ngayBaoCao": {"$lt": "${homNayStr}"}}&h={"$orderby": {"ngayBaoCao": -1}}&max=1`;
            const duLieu = await thucHienGoiApi(`report?${truyVan}`);

            if (duLieu.length > 0) {
                $('#vung-ket-qua-bao-cao-cu').val(taiTaoNoiDungBaoCao(duLieu[0]));
            } else {
                $('#vung-ket-qua-bao-cao-cu').val("Không tìm thấy dữ liệu báo cáo trước ngày hôm nay.");
            }
            modalXemBaoCaoCu.show();
        } catch (e) {
            hienThiThongBao("Lỗi tải lịch sử: " + e.message, "error");
        } finally {
            anTaiTrang();
        }
    });

    // KHỞI CHẠY
    khoiTaoGiaoDien(); 
    xayDungMenuGiaoDien(); 
    taiDuLieuTuServer(); 
});

import { KHOA_BO_NHO_TAM_CUC_BO } from './config.js';
import { hienThiThongBao, hienThiTaiTrang, anTaiTrang, dinhDangNgayHienThi, dinhDangNgayISO, trichXuatSoLieu } from './utils.js';
import { khoiTaoGiaoDien, xayDungMenuGiaoDien, apDungGiaoDien, luuCauHinhGiaoDien, apDungGiaoDienNgauNhien } from './theme.js';
import { thucHienGoiApi, ghiNhanTuongTacApi, lamMoiThongKeCsdl, datCheDoUngDung, layCheDoUngDung } from './api.js';
import { kiemTraTenTrongBaoCao, taoCauTrucGuiBaoCao } from './report.js';

$(function() {
    // --- TRẠNG THÁI ỨNG DỤNG ---
    let danhSachNhanVien = []; 
    let baoCaoLichSuGanNhat = null; 
    let ngayBaoCaoLichSu = null; 
    let nhanVienHienTai = null;
    let nhanVienCanXoa = null;

    // --- KHỞI TẠO MODAL BOOTSTRAP ---
    const modalThemNv = new bootstrap.Modal('#modal-them-nhan-vien');
    const modalDanBaoCao = new bootstrap.Modal('#modal-dan-bao-cao');
    const modalSuaBaoCao = new bootstrap.Modal('#modal-sua-bao-cao');
    const modalDanNhieuBaoCao = new bootstrap.Modal('#modal-dan-nhieu-bao-cao');
    const modalXacNhanXoa = new bootstrap.Modal('#modal-xac-nhan-xoa');
    const modalXemBaoCaoCu = new bootstrap.Modal('#modal-xem-bao-cao-cu');

    // --- CẬP NHẬT THÔNG TIN BUILD ---
    const phienBanBuild = "v1.6.1-patch";
    const thoiGianBuildStr = "2026.01.06 17:30"; 
    $('#thoi-gian-build').text(thoiGianBuildStr);
    $('.build-version').text(phienBanBuild);

    // --- SYSTEM MONITOR WIDGET ---
    $('#btn-toggle-monitor').on('click', function() {
        const $panel = $('#system-monitor-panel');
        if ($panel.hasClass('show')) {
            $panel.removeClass('show');
            setTimeout(() => $panel.hide(), 300); // Wait for transition
        } else {
            $panel.show();
            // Small delay to allow display:block to apply before transition
            setTimeout(() => $panel.addClass('show'), 10);
        }
    });

    const capNhatWidgetDb = (trucTuyen, slNv, slBaoCao, slTruyCap) => {
        const $cham = $('#cham-trang-thai-db');
        const $chu = $('#chu-trang-thai-db');
        const $nv = $('#so-luong-nv-db');
        const $bc = $('#so-luong-bao-cao-db');
        const $luong = $('#luong-truy-cap-api');

        if (trucTuyen) {
            $cham.removeClass('offline').addClass('online');
            $chu.text('Online');
        } else {
            $cham.removeClass('online').addClass('offline');
            $chu.text('Offline');
        }
        if (slNv !== null) $nv.text(`${slNv} NV`);
        if (slBaoCao !== null) $bc.text(`${slBaoCao} Rpt`);
        if (slTruyCap !== null) $luong.text(`${slTruyCap}`);
    }

    const $vungDsNv = $('#vung-danh-sach-nv');

    const capNhatNutTaoBaoCao = () => {
        const daBaoCao = danhSachNhanVien.filter(nv => nv.trangThai !== 'Chưa báo cáo').length;
        const tongSo = danhSachNhanVien.length;
        $('#nut-tao-bao-cao').html(`Tạo & Lưu Báo Cáo (${daBaoCao}/${tongSo})`);
    };

    const hienThiDanhSachNhanVien = () => {
        if (danhSachNhanVien.length === 0) {
             $vungDsNv.html('<div class="text-center py-3 text-muted">Danh sách trống.</div>');
             capNhatNutTaoBaoCao();
             return;
        }

        let html = '<div class="row g-2">';
        danhSachNhanVien.forEach(nv => {
            let lopNut = 'nut-ten-nv btn';
            if (nv.kiemTraTen === false) lopNut += ' sai-ten';
            else if (nv.trangThai === 'Đã báo cáo') lopNut += ' da-bao-cao';
            else if (nv.trangThai === 'Off') lopNut += ' nghi';

            html += `
                <div class="col-6">
                    <div class="input-group shadow-sm" style="border-radius: var(--btn-radius); overflow: hidden;">
                        <button class="${lopNut}" data-nv-ten="${nv.ten}" title="${nv.ten}">
                            ${nv.ten}
                        </button>
                        <button class="btn nut-sua-nv nut-sua-nhanh-nv" data-nv-ten="${nv.ten}">
                            <i class="fa-solid fa-pen-to-square"></i>
                        </button>
                        <button class="btn nut-xoa-nv nut-xoa-nv-kich-hoat" data-nv-id="${nv._id}" data-nv-ten="${nv.ten}">
                            <i class="fa-solid fa-trash-can"></i>
                        </button>
                    </div>
                </div>
            `;
        });
        html += '</div>';
        $vungDsNv.html(html);
        capNhatNutTaoBaoCao();
    };

    const luuVaoBoNhoTam = () => {
        const homNayStr = dinhDangNgayISO(new Date());
        const duLieu = {
            ngay: homNayStr,
            duLieuNv: danhSachNhanVien.map(n => ({
                _id: n._id, baoCao: n.baoCao, trangThai: n.trangThai, kiemTraTen: n.kiemTraTen
            })),
            vanBanKetQua: $('#vung-ket-qua-bao-cao').val()
        };
        localStorage.setItem(KHOA_BO_NHO_TAM_CUC_BO, JSON.stringify(duLieu));
    };

    const khoiPhuTuBoNhoTam = () => {
        const duLieuTho = localStorage.getItem(KHOA_BO_NHO_TAM_CUC_BO);
        if (!duLieuTho) return false;
        try {
            const duLieu = JSON.parse(duLieuTho);
            if (duLieu.ngay !== dinhDangNgayISO(new Date())) {
                localStorage.removeItem(KHOA_BO_NHO_TAM_CUC_BO);
                return false;
            }
            duLieu.duLieuNv.forEach(itemTam => {
                const nv = danhSachNhanVien.find(n => n._id === itemTam._id);
                if (nv && itemTam.baoCao) {
                    nv.baoCao = itemTam.baoCao; 
                    nv.trangThai = itemTam.trangThai; 
                    nv.kiemTraTen = itemTam.kiemTraTen;
                }
            });
            hienThiDanhSachNhanVien();
            if(duLieu.vanBanKetQua) $('#vung-ket-qua-bao-cao').val(duLieu.vanBanKetQua);
            return true;
        } catch (e) { return false; }
    };

    const taiDuLieuTuServer = async () => {
        hienThiTaiTrang("Đang tải danh sách FOS...");
        try {
            ghiNhanTuongTacApi().catch(() => {});

            const duLieuGoc = await thucHienGoiApi('nhanvien?h={"$orderby": {"Ten": 1}}');
            datCheDoUngDung('online');
            danhSachNhanVien = duLieuGoc.map(item => ({
                _id: item._id, ten: item.Ten, gioiTinh: item.GioiTinh,
                chiTieu: parseInt(item.ChiTieu, 10) || 50, baoCao: '',
                trangThai: 'Chưa báo cáo', kiemTraTen: null
            }));

            hienThiDanhSachNhanVien();

            // Ẩn loader ngay khi danh sách nhân viên hiện ra để user thao tác ngay
            anTaiTrang(); 

            // Các công việc nền tiếp tục chạy ngầm sau khi user đã có thể thao tác
            khoiPhuTuBoNhoTam();
            lamMoiThongKeCsdl(capNhatWidgetDb).catch(() => {});
            khoiPhuPhienLamViec().catch(() => {});

        } catch (error) {
            datCheDoUngDung('offline');
            hienThiThongBao("Đang hoạt động ngoại tuyến", "info");
            try {
                const phanHoi = await fetch('fos.txt');
                const text = await phanHoi.text();
                danhSachNhanVien = text.split('\n').filter(l => l.trim()).map((line, index) => {
                    const parts = line.split('|');
                    return {
                        _id: `local_${index}`, ten: parts[0]?.trim(), gioiTinh: parts[1]?.trim(), 
                        chiTieu: parseInt(parts[2]?.trim() || '50'), baoCao: '', 
                        trangThai: 'Chưa báo cáo', kiemTraTen: null
                    };
                });
                hienThiDanhSachNhanVien();
                anTaiTrang();
                khoiPhuTuBoNhoTam();
            } catch (e) {
                anTaiTrang();
            }
        }
    };

    const khoiPhuPhienLamViec = async () => {
        const homNayStr = dinhDangNgayISO(new Date());

        try {
            const bcHomNay = await thucHienGoiApi(`report?q={"ngayBaoCao": "${homNayStr}"}`);
            if (bcHomNay.length > 0) {
                bcHomNay[0].baoCaoFOS.forEach(item => {
                    const nv = danhSachNhanVien.find(n => n.ten === item.tenNhanVien);
                    if (nv && nv.baoCao === '') {
                        nv.trangThai = (item.OFF === 0 || item.OFF === '0') ? 'Đã báo cáo' : 'Off';
                        nv.baoCao = item.rawReport || `Fos ${item.tenNhanVien} ${nv.trangThai === 'Off' ? 'OFF' : ''}`;
                    }
                });
                hienThiDanhSachNhanVien();
            }
        } catch (e) {}

        // Lấy mốc lịch sử thực sự cũ hơn hôm nay
        try {
            const truyVanLichSu = `{"ngayBaoCao": {"$lt": "${homNayStr}"}}`;
            const sapXepLichSu = `{"$orderby": {"ngayBaoCao": -1}}`;
            const dsBcCu = await thucHienGoiApi(`report?q=${truyVanLichSu}&h=${sapXepLichSu}&max=1`);

            if (dsBcCu.length > 0) {
                const bcLichSu = dsBcCu[0];
                baoCaoLichSuGanNhat = bcLichSu;
                ngayBaoCaoLichSu = bcLichSu.ngayBaoCao;
                baoCaoLichSuGanNhat.duLieuNvLichSu = bcLichSu.baoCaoFOS.map(item => ({
                    ten: item.tenNhanVien, 
                    mtdMC: item.chiSoHieuSuat.saleTrongThang
                }));
                thucHienTaoBaoCao(null, true);
            }
        } catch (e) {}
    };

    const luuBaoCaoLenServer = async (cauTruc, chayNgam = false) => {
        if (layCheDoUngDung() === 'offline') return;
        if (chayNgam) $('#chi-bao-dang-luu').css('display', 'flex');
        try {
            const kiemTra = await thucHienGoiApi(`report?q={"ngayBaoCao": "${cauTruc.ngayBaoCao}"}`);
            if (kiemTra.length > 0) await thucHienGoiApi(`report/${kiemTra[0]._id}`, 'PUT', cauTruc);
            else await thucHienGoiApi('report', 'POST', cauTruc);
            lamMoiThongKeCsdl(capNhatWidgetDb);
        } catch (error) {} finally { setTimeout(() => $('#chi-bao-dang-luu').fadeOut(), 1000); }
    };

    const thucHienTaoBaoCao = (e, chiXem = false) => {
        danhSachNhanVien.sort((a, b) => b.chiTieu - a.chiTieu);
        hienThiDanhSachNhanVien();
        const quanLy = 'TNH';
        const ngayHienThi = dinhDangNgayHienThi(new Date());
        let tMC = 0, tNTB = 0, tETB = 0, nvActive = 0, tPos = 0, tAE = 0;
        let dsChiTiet = [];
        const banDoLichSu = new Map();
        if (baoCaoLichSuGanNhat?.duLieuNvLichSu) baoCaoLichSuGanNhat.duLieuNvLichSu.forEach(n => banDoLichSu.set(n.ten, n));

        danhSachNhanVien.forEach(nv => {
            const bieuTuong = nv.gioiTinh === 'Nữ' ? '👵' : '👨';
            const bc = nv.baoCao;
            let mtd = trichXuatSoLieu(bc, 'MTD MC');
            let ntb = trichXuatSoLieu(bc, 'NTB'), etb = trichXuatSoLieu(bc, 'ETB');
            let mcNay = ntb + etb;
            if (mcNay === 0) mcNay = trichXuatSoLieu(bc, ['Tổng MC', 'MC']);

            if ((nv.trangThai === 'Off' || mcNay === 0) && mtd === 0 && baoCaoLichSuGanNhat) {
                const nvLichSu = banDoLichSu.get(nv.ten);
                mtd = nvLichSu ? (nvLichSu.mtdMC || 0) : 0;
            }

            if (nv.trangThai === 'Off') {
                const matchLyDo = bc.match(/^Fos\s+\S+\s+(.*)$/i);
                const lyDo = (matchLyDo && matchLyDo[1] && matchLyDo[1].toUpperCase() !== 'OFF') ? matchLyDo[1] : 'OFF';
                dsChiTiet.push(`${bieuTuong}${nv.ten}: ${lyDo}/${mtd}/${nv.chiTieu}`);
            } else {
                nvActive++;
                tMC += mcNay; tNTB += ntb; tETB += etb;
                tPos += trichXuatSoLieu(bc, 'Pos'); tAE += trichXuatSoLieu(bc, ['AE+', 'AE Plus']);
                dsChiTiet.push(`${bieuTuong}${nv.ten}: ${mcNay}/${mtd}/${nv.chiTieu}`);
            }
        });

        const nsbqNTB = (nvActive > 0) ? (tNTB / nvActive).toFixed(2) : '0.00';
        const nsbqETB = (nvActive > 0) ? (tETB / nvActive).toFixed(2) : '0.00';
        let ketQua = `${quanLy} ngày ${ngayHienThi}\n🔥${danhSachNhanVien.length} FOS – ${tMC} MC\n✅NTB: ${tNTB}\n✅NSBQ NTB: ${nsbqNTB}\n✅ETB: ${tETB}\n✅NSBQ ETB: ${nsbqETB}\n✅AE+: ${tAE}\n✅Pos: ${tPos}/${danhSachNhanVien.length * 3}\n\n⭐️Active ${nvActive}/${danhSachNhanVien.length}\n${dsChiTiet.join('\n')}`;
        $('#vung-ket-qua-bao-cao').val(ketQua);

        if (!chiXem) {
            const thongKe = { tongFOS: danhSachNhanVien.length, tongMC: tMC, tongNTB: tNTB, nsbqNTB, tongETB: tETB, nsbqETB, tongPosThucHien: tPos, posChiTieu: danhSachNhanVien.length * 3, activeFOS: nvActive, tongAEPlus: tAE };
            luuBaoCaoLenServer(taoCauTrucGuiBaoCao(danhSachNhanVien, baoCaoLichSuGanNhat, thongKe), true);
        }
    };

    // --- HELPER TẠO BÁO CÁO TỪ DB OBJECT ---
    const taiTaoNoiDungBaoCao = (bc) => {
        const ngayHienThi = dinhDangNgayHienThi(bc.ngayBaoCao);
        const thongKe = bc.tongKetToanDoi;
        const dsNv = bc.baoCaoFOS;
        const quanLy = 'TNH'; // Tên quản lý mặc định

        // Tái tạo phần Header
        let ketQua = `${quanLy} ngày ${ngayHienThi}\n`;

        if (thongKe) {
            const tMC = thongKe.tongSoMC || 0;
            const tFOS = thongKe.tongSoFOS || 0;
            const tNTB = thongKe.tongSoNTB || 0;
            const nsbqNTB = (thongKe.NSBQ_NTB !== undefined && thongKe.NSBQ_NTB !== null) ? Number(thongKe.NSBQ_NTB).toFixed(2) : '0.00';
            const tETB = thongKe.tongSoETB || 0;
            const nsbqETB = (thongKe.NSBQ_ETB !== undefined && thongKe.NSBQ_ETB !== null) ? Number(thongKe.NSBQ_ETB).toFixed(2) : '0.00';
            const tAE = thongKe.tongSoAEPlus || 0;
            const tPos = thongKe.tyLePOS || "0/0";
            const tActive = thongKe.tyLeActiveFOS || "0/0";

            ketQua += `🔥${tFOS} FOS – ${tMC} MC\n`;
            ketQua += `✅NTB: ${tNTB}\n`;
            ketQua += `✅NSBQ NTB: ${nsbqNTB}\n`;
            ketQua += `✅ETB: ${tETB}\n`;
            ketQua += `✅NSBQ ETB: ${nsbqETB}\n`;
            ketQua += `✅AE+: ${tAE}\n`;
            ketQua += `✅Pos: ${tPos}\n\n`;
            ketQua += `⭐️Active ${tActive}\n`;
        }

        // Tái tạo danh sách nhân viên
        if (dsNv && dsNv.length > 0) {
            dsNv.forEach(n => {
                 // Tìm nhân viên trong danh sách hiện tại để lấy giới tính (icon)
                 const nvHienTai = danhSachNhanVien.find(nv => nv.ten === n.tenNhanVien);
                 // Mặc định icon Nam nếu không tìm thấy hoặc chưa load
                 const icon = nvHienTai ? (nvHienTai.gioiTinh === 'Nữ' ? '👵' : '👨') : '👨';

                 const sale = n.chiSoHieuSuat?.saleHomNay || 0;
                 const mtd = n.chiSoHieuSuat?.saleTrongThang || 0;
                 const chiTieu = n.chiSoHieuSuat?.chiTieu || 0;

                 let statusStr = `${sale}/${mtd}/${chiTieu}`;

                 // Xử lý logic hiển thị OFF (tương tự như thucHienTaoBaoCao)
                 if (n.OFF && n.OFF !== 0 && n.OFF !== '0') {
                     const lyDo = (n.OFF === 1 || n.OFF === '1') ? 'OFF' : n.OFF;
                     statusStr = `${lyDo}/${mtd}/${chiTieu}`;
                 }

                 ketQua += `${icon}${n.tenNhanVien}: ${statusStr}\n`;
            });
        }
        return ketQua;
    };

    // --- SỰ KIỆN GIAO DIỆN ---
    $('body').on('click', '.lua-chon-giao-dien', function(e) {
        e.preventDefault();
        const theme = $(this).data('theme');
        const mode = $(this).data('mode');
        const lop = `theme-${theme}-${mode}`;
        apDungGiaoDien(lop); 
        luuCauHinhGiaoDien(lop);
        hienThiThongBao(`Giao diện: ${theme} ${mode}`);
    });

    $('#nut-giao-dien-ngau-nhien').on('click', e => { 
        e.preventDefault(); 
        luuCauHinhGiaoDien('random'); 
        apDungGiaoDienNgauNhien(); 
    });

    $('#nut-luu-nv-moi').on('click', async () => {
        const ten = $('#ten-nv-modal').val().trim(), gt = $('#gioi-tinh-nv-modal').val(), ct = parseInt($('#chi-tieu-nv-modal').val()) || 0;
        if (ten && !danhSachNhanVien.some(n => n.ten.toLowerCase() === ten.toLowerCase())) {
            hienThiTaiTrang("Đang lưu nhân viên...");
            try { await thucHienGoiApi('nhanvien', 'POST', { Ten: ten, GioiTinh: gt, ChiTieu: ct }); modalThemNv.hide(); taiDuLieuTuServer(); }
            catch (e) { hienThiThongBao(e.message, 'error'); } finally { anTaiTrang(); }
        }
    });

    $vungDsNv.on('click', '.nut-xoa-nv-kich-hoat', function() {
        nhanVienCanXoa = { id: $(this).data('nv-id'), ten: $(this).data('nv-ten') };
        $('#noi-dung-xac-nhan-xoa').text(`Xoá nhân viên "${nhanVienCanXoa.ten}"?`);
        modalXacNhanXoa.show();
    });

    $('#nut-xac-nhan-xoa-vinh-vien').on('click', async () => {
        if (!nhanVienCanXoa) return;
        hienThiTaiTrang("Đang xoá vĩnh viễn...");
        try { await thucHienGoiApi(`nhanvien/${nhanVienCanXoa.id}`, 'DELETE'); taiDuLieuTuServer(); }
        catch (e) { hienThiThongBao(e.message, 'error'); } finally { anTaiTrang(); modalXacNhanXoa.hide(); }
    });

    $vungDsNv.on('click', '.nut-ten-nv', function() {
        nhanVienHienTai = $(this).data('nv-ten');
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { 
            $('#modalDanBaoCaoLabel').text(`Báo cáo của ${nhanVienHienTai}`); 
            $('#noi-dung-bao-cao-nhap').val(nv.baoCao); 
            modalDanBaoCao.show(); 
        }
    });

    $('#nut-luu-bao-cao-don').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const nd = $('#noi-dung-bao-cao-nhap').val();
            nv.baoCao = nd; nv.trangThai = 'Đã báo cáo'; kiemTraTenTrongBaoCao(nv, nd);
            hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide();
        }
    });

    $('#nut-danh-dau-off').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { nv.baoCao = `Fos ${nv.ten} OFF`; nv.trangThai = 'Off'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide(); }
    });

    $('#nut-xac-nhan-off-co-ly-do').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { nv.baoCao = `Fos ${nv.ten} ${$('#ly-do-off-nhap').val().trim() || 'OFF'}`; nv.trangThai = 'Off'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide(); }
    });

    $vungDsNv.on('click', '.nut-sua-nhanh-nv', function() {
        nhanVienHienTai = $(this).data('nv-ten');
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const bc = nv.baoCao;
            $('#tieu-de-modal-sua-bao-cao').text(`Sửa nhanh: ${nhanVienHienTai}`);
            $('#ntb-sua').val(trichXuatSoLieu(bc, 'NTB')); $('#etb-sua').val(trichXuatSoLieu(bc, 'ETB'));
            $('#pos-sua').val(trichXuatSoLieu(bc, 'Pos')); $('#aeplus-sua').val(trichXuatSoLieu(bc, ['AE+', 'AE Plus']));
            $('#mtd-sua').val(trichXuatSoLieu(bc, 'MTD MC'));
            modalSuaBaoCao.show();
        }
    });

    $('#nut-xac-nhan-sua-bao-cao').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const n = parseInt($('#ntb-sua').val()) || 0, e = parseInt($('#etb-sua').val()) || 0;
            nv.baoCao = `Fos ${nv.ten}\nTổng MC: ${n+e}\nNTB: ${n}\nETB: ${e}\nAE+: ${$('#aeplus-sua').val() || 0}\nPos: ${$('#pos-sua').val() || 0}\nMTD MC: ${$('#mtd-sua').val() || 0}`;
            nv.trangThai = 'Đã báo cáo'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalSuaBaoCao.hide();
        }
    });

    $('#nut-dan-tu-bo-nho').on('click', async () => {
        try { const t = await navigator.clipboard.readText(); if (t) $('#noi-dung-bao-cao-nhap').val(t); } catch(e) {}
    });

    $('#nut-dan-hang-loat').on('click', async () => {
        try { const t = await navigator.clipboard.readText(); if (t) $('#noi-dung-nhieu-bao-cao-nhap').val(t); } catch(e) {}
    });

    $('#nut-xu-ly-nhieu-bao-cao').on('click', () => {
        const vanBan = $('#noi-dung-nhieu-bao-cao-nhap').val().trim();
        if (!vanBan) return;
        const khoiBaoCao = vanBan.split(/(?=^Fos\s)/im); 
        khoiBaoCao.forEach(khoi => {
            const khoiTrim = khoi.trim();
            const nv = danhSachNhanVien.find(n => {
                const tenEscape = n.ten.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
                return new RegExp(`^Fos\\s+${tenEscape}(?=\\s|$)`, 'i').test(khoiTrim);
            });
            if (nv) { nv.baoCao = khoiTrim; nv.trangThai = 'Đã báo cáo'; kiemTraTenTrongBaoCao(nv, khoiTrim); }
        });
        modalDanNhieuBaoCao.hide(); hienThiDanhSachNhanVien(); luuVaoBoNhoTam();
        hienThiThongBao("Đã xử lý xong báo cáo hàng loạt.");
    });

    $('#nut-tao-bao-cao').on('click', () => thucHienTaoBaoCao());
    $('#nut-sao-chep').on('click', function() {
        const $btn = $(this);
        navigator.clipboard.writeText($('#vung-ket-qua-bao-cao').val()).then(() => {
            hienThiThongBao('Đã sao chép báo cáo vào bộ nhớ tạm!');
            $btn.html('<i class="fa-solid fa-check"></i> Đã chép').addClass('btn-success').removeClass('btn-primary');
            setTimeout(() => $btn.html('<i class="fa-regular fa-copy"></i> Sao chép').removeClass('btn-success').addClass('btn-primary'), 2000);
        });
    });

    // --- XỬ LÝ SỰ KIỆN XEM BÁO CÁO CŨ (MỚI) ---
    $('#nut-xem-bao-cao-cu').on('click', async () => {
        hienThiTaiTrang("Đang tải báo cáo cũ...");
        try {
            const homNayStr = dinhDangNgayISO(new Date());
            // Lấy báo cáo có ngày < ngày hôm nay, sắp xếp giảm dần, lấy 1
            const truyVan = `q={"ngayBaoCao": {"$lt": "${homNayStr}"}}&h={"$orderby": {"ngayBaoCao": -1}}&max=1`;
            const duLieu = await thucHienGoiApi(`report?${truyVan}`);

            if (duLieu.length > 0) {
                $('#vung-ket-qua-bao-cao-cu').val(taiTaoNoiDungBaoCao(duLieu[0]));
            } else {
                $('#vung-ket-qua-bao-cao-cu').val("Không tìm thấy dữ liệu báo cáo trước ngày hôm nay.");
            }
            modalXemBaoCaoCu.show();
        } catch (e) {
            hienThiThongBao("Lỗi tải lịch sử: " + e.message, "error");
        } finally {
            anTaiTrang();
        }
    });

    // KHỞI CHẠY
    khoiTaoGiaoDien(); 
    xayDungMenuGiaoDien(); 
    taiDuLieuTuServer(); 
});

import { KHOA_BO_NHO_TAM_CUC_BO } from './config.js';
import { hienThiThongBao, hienThiTaiTrang, anTaiTrang, dinhDangNgayHienThi, dinhDangNgayISO, trichXuatSoLieu } from './utils.js';
import { khoiTaoGiaoDien, xayDungMenuGiaoDien, apDungGiaoDien, luuCauHinhGiaoDien, apDungGiaoDienNgauNhien } from './theme.js';
import { thucHienGoiApi, ghiNhanTuongTacApi, lamMoiThongKeCsdl, datCheDoUngDung, layCheDoUngDung } from './api.js';
import { kiemTraTenTrongBaoCao, taoCauTrucGuiBaoCao } from './report.js';

$(function() {
    // --- TRẠNG THÁI ỨNG DỤNG ---
    let danhSachNhanVien = []; 
    let baoCaoLichSuGanNhat = null; 
    let ngayBaoCaoLichSu = null; 
    let nhanVienHienTai = null;
    let nhanVienCanXoa = null;

    // --- KHỞI TẠO MODAL BOOTSTRAP ---
    const modalThemNv = new bootstrap.Modal('#modal-them-nhan-vien');
    const modalDanBaoCao = new bootstrap.Modal('#modal-dan-bao-cao');
    const modalSuaBaoCao = new bootstrap.Modal('#modal-sua-bao-cao');
    const modalDanNhieuBaoCao = new bootstrap.Modal('#modal-dan-nhieu-bao-cao');
    const modalXacNhanXoa = new bootstrap.Modal('#modal-xac-nhan-xoa');
    const modalXemBaoCaoCu = new bootstrap.Modal('#modal-xem-bao-cao-cu');

    // --- CẬP NHẬT THÔNG TIN BUILD ---
    const phienBanBuild = "v1.7.0-beta";
    const thoiGianBuildStr = "2026.01.06 17:45"; 
    $('#thoi-gian-build').text(thoiGianBuildStr);
    $('.build-version').text(phienBanBuild);

    // --- SYSTEM MONITOR WIDGET ---
    $('#btn-toggle-monitor').on('click', function() {
        const $panel = $('#system-monitor-panel');
        if ($panel.hasClass('show')) {
            $panel.removeClass('show');
            setTimeout(() => $panel.hide(), 300); // Wait for transition
        } else {
            $panel.show();
            // Small delay to allow display:block to apply before transition
            setTimeout(() => $panel.addClass('show'), 10);
        }
    });

    const capNhatWidgetDb = (trucTuyen, slNv, slBaoCao, slTruyCap) => {
        const $cham = $('#cham-trang-thai-db');
        const $chu = $('#chu-trang-thai-db');
        const $nv = $('#so-luong-nv-db');
        const $bc = $('#so-luong-bao-cao-db');
        const $luong = $('#luong-truy-cap-api');

        if (trucTuyen) {
            $cham.removeClass('offline').addClass('online');
            $chu.text('Online');
        } else {
            $cham.removeClass('online').addClass('offline');
            $chu.text('Offline');
        }
        if (slNv !== null) $nv.text(`${slNv} NV`);
        if (slBaoCao !== null) $bc.text(`${slBaoCao} Rpt`);
        if (slTruyCap !== null) $luong.text(`${slTruyCap}`);
    }

    const $vungDsNv = $('#vung-danh-sach-nv');

    const capNhatNutTaoBaoCao = () => {
        const daBaoCao = danhSachNhanVien.filter(nv => nv.trangThai !== 'Chưa báo cáo').length;
        const tongSo = danhSachNhanVien.length;
        $('#nut-tao-bao-cao').html(`Tạo & Lưu Báo Cáo (${daBaoCao}/${tongSo})`);
    };

    const hienThiDanhSachNhanVien = () => {
        if (danhSachNhanVien.length === 0) {
             $vungDsNv.html('<div class="text-center py-3 text-muted">Danh sách trống.</div>');
             capNhatNutTaoBaoCao();
             return;
        }

        let html = '<div class="row g-2">';
        danhSachNhanVien.forEach(nv => {
            let lopNut = 'nut-ten-nv btn';
            if (nv.kiemTraTen === false) lopNut += ' sai-ten';
            else if (nv.trangThai === 'Đã báo cáo') lopNut += ' da-bao-cao';
            else if (nv.trangThai === 'Off') lopNut += ' nghi';

            html += `
                <div class="col-6">
                    <div class="input-group shadow-sm" style="border-radius: var(--btn-radius); overflow: hidden;">
                        <button class="${lopNut}" data-nv-ten="${nv.ten}" title="${nv.ten}">
                            ${nv.ten}
                        </button>
                        <button class="btn nut-sua-nv nut-sua-nhanh-nv" data-nv-ten="${nv.ten}">
                            <i class="fa-solid fa-pen-to-square"></i>
                        </button>
                        <button class="btn nut-xoa-nv nut-xoa-nv-kich-hoat" data-nv-id="${nv._id}" data-nv-ten="${nv.ten}">
                            <i class="fa-solid fa-trash-can"></i>
                        </button>
                    </div>
                </div>
            `;
        });
        html += '</div>';
        $vungDsNv.html(html);
        capNhatNutTaoBaoCao();
    };

    const luuVaoBoNhoTam = () => {
        const homNayStr = dinhDangNgayISO(new Date());
        const duLieu = {
            ngay: homNayStr,
            duLieuNv: danhSachNhanVien.map(n => ({
                _id: n._id, baoCao: n.baoCao, trangThai: n.trangThai, kiemTraTen: n.kiemTraTen
            })),
            vanBanKetQua: $('#vung-ket-qua-bao-cao').val()
        };
        localStorage.setItem(KHOA_BO_NHO_TAM_CUC_BO, JSON.stringify(duLieu));
    };

    const khoiPhuTuBoNhoTam = () => {
        const duLieuTho = localStorage.getItem(KHOA_BO_NHO_TAM_CUC_BO);
        if (!duLieuTho) return false;
        try {
            const duLieu = JSON.parse(duLieuTho);
            if (duLieu.ngay !== dinhDangNgayISO(new Date())) {
                localStorage.removeItem(KHOA_BO_NHO_TAM_CUC_BO);
                return false;
            }
            duLieu.duLieuNv.forEach(itemTam => {
                const nv = danhSachNhanVien.find(n => n._id === itemTam._id);
                if (nv && itemTam.baoCao) {
                    nv.baoCao = itemTam.baoCao; 
                    nv.trangThai = itemTam.trangThai; 
                    nv.kiemTraTen = itemTam.kiemTraTen;
                }
            });
            hienThiDanhSachNhanVien();
            if(duLieu.vanBanKetQua) $('#vung-ket-qua-bao-cao').val(duLieu.vanBanKetQua);
            return true;
        } catch (e) { return false; }
    };

    const taiDuLieuTuServer = async () => {
        hienThiTaiTrang("Đang tải danh sách FOS...");
        try {
            ghiNhanTuongTacApi().catch(() => {});

            const duLieuGoc = await thucHienGoiApi('nhanvien?h={"$orderby": {"Ten": 1}}');
            datCheDoUngDung('online');
            danhSachNhanVien = duLieuGoc.map(item => ({
                _id: item._id, ten: item.Ten, gioiTinh: item.GioiTinh,
                chiTieu: parseInt(item.ChiTieu, 10) || 50, baoCao: '',
                trangThai: 'Chưa báo cáo', kiemTraTen: null
            }));

            hienThiDanhSachNhanVien();

            // Ẩn loader ngay khi danh sách nhân viên hiện ra để user thao tác ngay
            anTaiTrang(); 

            // Các công việc nền tiếp tục chạy ngầm sau khi user đã có thể thao tác
            khoiPhuTuBoNhoTam();
            lamMoiThongKeCsdl(capNhatWidgetDb).catch(() => {});
            khoiPhuPhienLamViec().catch(() => {});

        } catch (error) {
            datCheDoUngDung('offline');
            hienThiThongBao("Đang hoạt động ngoại tuyến", "info");
            try {
                const phanHoi = await fetch('fos.txt');
                const text = await phanHoi.text();
                danhSachNhanVien = text.split('\n').filter(l => l.trim()).map((line, index) => {
                    const parts = line.split('|');
                    return {
                        _id: `local_${index}`, ten: parts[0]?.trim(), gioiTinh: parts[1]?.trim(), 
                        chiTieu: parseInt(parts[2]?.trim() || '50'), baoCao: '', 
                        trangThai: 'Chưa báo cáo', kiemTraTen: null
                    };
                });
                hienThiDanhSachNhanVien();
                anTaiTrang();
                khoiPhuTuBoNhoTam();
            } catch (e) {
                anTaiTrang();
            }
        }
    };

    const khoiPhuPhienLamViec = async () => {
        const homNayStr = dinhDangNgayISO(new Date());

        try {
            const bcHomNay = await thucHienGoiApi(`report?q={"ngayBaoCao": "${homNayStr}"}`);
            if (bcHomNay.length > 0) {
                bcHomNay[0].baoCaoFOS.forEach(item => {
                    const nv = danhSachNhanVien.find(n => n.ten === item.tenNhanVien);
                    if (nv && nv.baoCao === '') {
                        nv.trangThai = (item.OFF === 0 || item.OFF === '0') ? 'Đã báo cáo' : 'Off';
                        nv.baoCao = item.rawReport || `Fos ${item.tenNhanVien} ${nv.trangThai === 'Off' ? 'OFF' : ''}`;
                    }
                });
                hienThiDanhSachNhanVien();
            }
        } catch (e) {}

        // Lấy mốc lịch sử thực sự cũ hơn hôm nay
        try {
            const truyVanLichSu = `{"ngayBaoCao": {"$lt": "${homNayStr}"}}`;
            const sapXepLichSu = `{"$orderby": {"ngayBaoCao": -1}}`;
            const dsBcCu = await thucHienGoiApi(`report?q=${truyVanLichSu}&h=${sapXepLichSu}&max=1`);

            if (dsBcCu.length > 0) {
                const bcLichSu = dsBcCu[0];
                baoCaoLichSuGanNhat = bcLichSu;
                ngayBaoCaoLichSu = bcLichSu.ngayBaoCao;
                baoCaoLichSuGanNhat.duLieuNvLichSu = bcLichSu.baoCaoFOS.map(item => ({
                    ten: item.tenNhanVien, 
                    mtdMC: item.chiSoHieuSuat.saleTrongThang
                }));
                thucHienTaoBaoCao(null, true);
            }
        } catch (e) {}
    };

    const luuBaoCaoLenServer = async (cauTruc, chayNgam = false) => {
        if (layCheDoUngDung() === 'offline') return;
        if (chayNgam) $('#chi-bao-dang-luu').css('display', 'flex');
        try {
            const kiemTra = await thucHienGoiApi(`report?q={"ngayBaoCao": "${cauTruc.ngayBaoCao}"}`);
            if (kiemTra.length > 0) await thucHienGoiApi(`report/${kiemTra[0]._id}`, 'PUT', cauTruc);
            else await thucHienGoiApi('report', 'POST', cauTruc);
            lamMoiThongKeCsdl(capNhatWidgetDb);
        } catch (error) {} finally { setTimeout(() => $('#chi-bao-dang-luu').fadeOut(), 1000); }
    };

    const thucHienTaoBaoCao = (e, chiXem = false) => {
        danhSachNhanVien.sort((a, b) => b.chiTieu - a.chiTieu);
        hienThiDanhSachNhanVien();
        const quanLy = 'TNH';
        const ngayHienThi = dinhDangNgayHienThi(new Date());
        let tMC = 0, tNTB = 0, tETB = 0, nvActive = 0, tPos = 0, tAE = 0;
        let dsChiTiet = [];
        const banDoLichSu = new Map();
        if (baoCaoLichSuGanNhat?.duLieuNvLichSu) baoCaoLichSuGanNhat.duLieuNvLichSu.forEach(n => banDoLichSu.set(n.ten, n));

        danhSachNhanVien.forEach(nv => {
            const bieuTuong = nv.gioiTinh === 'Nữ' ? '👵' : '👨';
            const bc = nv.baoCao;
            let mtd = trichXuatSoLieu(bc, 'MTD MC');
            let ntb = trichXuatSoLieu(bc, 'NTB'), etb = trichXuatSoLieu(bc, 'ETB');
            let mcNay = ntb + etb;
            if (mcNay === 0) mcNay = trichXuatSoLieu(bc, ['Tổng MC', 'MC']);

            if ((nv.trangThai === 'Off' || mcNay === 0) && mtd === 0 && baoCaoLichSuGanNhat) {
                const nvLichSu = banDoLichSu.get(nv.ten);
                mtd = nvLichSu ? (nvLichSu.mtdMC || 0) : 0;
            }

            if (nv.trangThai === 'Off') {
                const matchLyDo = bc.match(/^Fos\s+\S+\s+(.*)$/i);
                const lyDo = (matchLyDo && matchLyDo[1] && matchLyDo[1].toUpperCase() !== 'OFF') ? matchLyDo[1] : 'OFF';
                dsChiTiet.push(`${bieuTuong}${nv.ten}: ${lyDo}/${mtd}/${nv.chiTieu}`);
            } else {
                nvActive++;
                tMC += mcNay; tNTB += ntb; tETB += etb;
                tPos += trichXuatSoLieu(bc, 'Pos'); tAE += trichXuatSoLieu(bc, ['AE+', 'AE Plus']);
                dsChiTiet.push(`${bieuTuong}${nv.ten}: ${mcNay}/${mtd}/${nv.chiTieu}`);
            }
        });

        const nsbqNTB = (nvActive > 0) ? (tNTB / nvActive).toFixed(2) : '0.00';
        const nsbqETB = (nvActive > 0) ? (tETB / nvActive).toFixed(2) : '0.00';
        let ketQua = `${quanLy} ngày ${ngayHienThi}\n🔥${danhSachNhanVien.length} FOS – ${tMC} MC\n✅NTB: ${tNTB}\n✅NSBQ NTB: ${nsbqNTB}\n✅ETB: ${tETB}\n✅NSBQ ETB: ${nsbqETB}\n✅AE+: ${tAE}\n✅Pos: ${tPos}/${danhSachNhanVien.length * 3}\n\n⭐️Active ${nvActive}/${danhSachNhanVien.length}\n${dsChiTiet.join('\n')}`;
        $('#vung-ket-qua-bao-cao').val(ketQua);

        if (!chiXem) {
            const thongKe = { tongFOS: danhSachNhanVien.length, tongMC: tMC, tongNTB: tNTB, nsbqNTB, tongETB: tETB, nsbqETB, tongPosThucHien: tPos, posChiTieu: danhSachNhanVien.length * 3, activeFOS: nvActive, tongAEPlus: tAE };
            luuBaoCaoLenServer(taoCauTrucGuiBaoCao(danhSachNhanVien, baoCaoLichSuGanNhat, thongKe), true);
        }
    };

    // --- HELPER TẠO BÁO CÁO TỪ DB OBJECT ---
    const taiTaoNoiDungBaoCao = (bc) => {
        const ngayHienThi = dinhDangNgayHienThi(bc.ngayBaoCao);
        const thongKe = bc.tongKetToanDoi;
        const dsNv = bc.baoCaoFOS;
        const quanLy = 'TNH'; // Tên quản lý mặc định

        // Tái tạo phần Header
        let ketQua = `${quanLy} ngày ${ngayHienThi}\n`;

        if (thongKe) {
            const tMC = thongKe.tongSoMC || 0;
            const tFOS = thongKe.tongSoFOS || 0;
            const tNTB = thongKe.tongSoNTB || 0;
            const nsbqNTB = (thongKe.NSBQ_NTB !== undefined && thongKe.NSBQ_NTB !== null) ? Number(thongKe.NSBQ_NTB).toFixed(2) : '0.00';
            const tETB = thongKe.tongSoETB || 0;
            const nsbqETB = (thongKe.NSBQ_ETB !== undefined && thongKe.NSBQ_ETB !== null) ? Number(thongKe.NSBQ_ETB).toFixed(2) : '0.00';
            const tAE = thongKe.tongSoAEPlus || 0;
            const tPos = thongKe.tyLePOS || "0/0";
            const tActive = thongKe.tyLeActiveFOS || "0/0";

            ketQua += `🔥${tFOS} FOS – ${tMC} MC\n`;
            ketQua += `✅NTB: ${tNTB}\n`;
            ketQua += `✅NSBQ NTB: ${nsbqNTB}\n`;
            ketQua += `✅ETB: ${tETB}\n`;
            ketQua += `✅NSBQ ETB: ${nsbqETB}\n`;
            ketQua += `✅AE+: ${tAE}\n`;
            ketQua += `✅Pos: ${tPos}\n\n`;
            ketQua += `⭐️Active ${tActive}\n`;
        }

        // Tái tạo danh sách nhân viên
        if (dsNv && dsNv.length > 0) {
            dsNv.forEach(n => {
                 // Tìm nhân viên trong danh sách hiện tại để lấy giới tính (icon)
                 const nvHienTai = danhSachNhanVien.find(nv => nv.ten === n.tenNhanVien);
                 // Mặc định icon Nam nếu không tìm thấy hoặc chưa load
                 const icon = nvHienTai ? (nvHienTai.gioiTinh === 'Nữ' ? '👵' : '👨') : '👨';

                 const sale = n.chiSoHieuSuat?.saleHomNay || 0;
                 const mtd = n.chiSoHieuSuat?.saleTrongThang || 0;
                 const chiTieu = n.chiSoHieuSuat?.chiTieu || 0;

                 let statusStr = `${sale}/${mtd}/${chiTieu}`;

                 // Xử lý logic hiển thị OFF (tương tự như thucHienTaoBaoCao)
                 if (n.OFF && n.OFF !== 0 && n.OFF !== '0') {
                     const lyDo = (n.OFF === 1 || n.OFF === '1') ? 'OFF' : n.OFF;
                     statusStr = `${lyDo}/${mtd}/${chiTieu}`;
                 }

                 ketQua += `${icon}${n.tenNhanVien}: ${statusStr}\n`;
            });
        }
        return ketQua;
    };

    // --- HELPER LẤY MTD LỊCH SỬ ---
    const layMtdLichSu = (tenNv) => {
        if (!baoCaoLichSuGanNhat || !baoCaoLichSuGanNhat.duLieuNvLichSu) return 0;
        const nvCu = baoCaoLichSuGanNhat.duLieuNvLichSu.find(n => n.ten === tenNv);
        return nvCu ? (nvCu.mtdMC || 0) : 0;
    };

    // --- SỰ KIỆN GIAO DIỆN ---
    $('body').on('click', '.lua-chon-giao-dien', function(e) {
        e.preventDefault();
        const theme = $(this).data('theme');
        const mode = $(this).data('mode');
        const lop = `theme-${theme}-${mode}`;
        apDungGiaoDien(lop); 
        luuCauHinhGiaoDien(lop);
        hienThiThongBao(`Giao diện: ${theme} ${mode}`);
    });

    $('#nut-giao-dien-ngau-nhien').on('click', e => { 
        e.preventDefault(); 
        luuCauHinhGiaoDien('random'); 
        apDungGiaoDienNgauNhien(); 
    });

    $('#nut-luu-nv-moi').on('click', async () => {
        const ten = $('#ten-nv-modal').val().trim(), gt = $('#gioi-tinh-nv-modal').val(), ct = parseInt($('#chi-tieu-nv-modal').val()) || 0;
        if (ten && !danhSachNhanVien.some(n => n.ten.toLowerCase() === ten.toLowerCase())) {
            hienThiTaiTrang("Đang lưu nhân viên...");
            try { await thucHienGoiApi('nhanvien', 'POST', { Ten: ten, GioiTinh: gt, ChiTieu: ct }); modalThemNv.hide(); taiDuLieuTuServer(); }
            catch (e) { hienThiThongBao(e.message, 'error'); } finally { anTaiTrang(); }
        }
    });

    $vungDsNv.on('click', '.nut-xoa-nv-kich-hoat', function() {
        nhanVienCanXoa = { id: $(this).data('nv-id'), ten: $(this).data('nv-ten') };
        $('#noi-dung-xac-nhan-xoa').text(`Xoá nhân viên "${nhanVienCanXoa.ten}"?`);
        modalXacNhanXoa.show();
    });

    $('#nut-xac-nhan-xoa-vinh-vien').on('click', async () => {
        if (!nhanVienCanXoa) return;
        hienThiTaiTrang("Đang xoá vĩnh viễn...");
        try { await thucHienGoiApi(`nhanvien/${nhanVienCanXoa.id}`, 'DELETE'); taiDuLieuTuServer(); }
        catch (e) { hienThiThongBao(e.message, 'error'); } finally { anTaiTrang(); modalXacNhanXoa.hide(); }
    });

    $vungDsNv.on('click', '.nut-ten-nv', function() {
        nhanVienHienTai = $(this).data('nv-ten');
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { 
            $('#modalDanBaoCaoLabel').text(`Báo cáo của ${nhanVienHienTai}`); 
            $('#noi-dung-bao-cao-nhap').val(nv.baoCao); 
            modalDanBaoCao.show(); 
        }
    });

    $('#nut-luu-bao-cao-don').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const nd = $('#noi-dung-bao-cao-nhap').val();
            nv.baoCao = nd; 

            // Logic thông minh để xác định trạng thái
            // Nếu dòng đầu tiên có chứa "OFF" (hoặc lý do) sau tên Fos, thì giữ nguyên trạng thái là Off
            // Ví dụ: "Fos Toan OFF" hoặc "Fos Toan Nghỉ phép"
            const dongDau = nd.trim().split('\n')[0];
            const tenEscape = nv.ten.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
            const regexLyDo = new RegExp(`^Fos\\s+${tenEscape}\\s+(.+)$`, 'i');
            const match = dongDau.match(regexLyDo);

            if (match && match[1].trim()) {
                 nv.trangThai = 'Off';
            } else {
                 nv.trangThai = 'Đã báo cáo';
            }

            kiemTraTenTrongBaoCao(nv, nd);
            hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide();
        }
    });

    $('#nut-danh-dau-off').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { 
            const mtdCu = layMtdLichSu(nv.ten);
            nv.baoCao = `Fos ${nv.ten} OFF\nMTD MC: ${mtdCu}`; 
            nv.trangThai = 'Off'; 
            hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide(); 
        }
    });

    $('#nut-xac-nhan-off-co-ly-do').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { 
            const mtdCu = layMtdLichSu(nv.ten);
            const lyDo = $('#ly-do-off-nhap').val().trim() || 'OFF';
            nv.baoCao = `Fos ${nv.ten} ${lyDo}\nMTD MC: ${mtdCu}`; 
            nv.trangThai = 'Off'; 
            hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide(); 
        }
    });

    $vungDsNv.on('click', '.nut-sua-nhanh-nv', function() {
        nhanVienHienTai = $(this).data('nv-ten');
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const bc = nv.baoCao;
            $('#tieu-de-modal-sua-bao-cao').text(`Sửa nhanh: ${nhanVienHienTai}`);
            $('#ntb-sua').val(trichXuatSoLieu(bc, 'NTB')); $('#etb-sua').val(trichXuatSoLieu(bc, 'ETB'));
            $('#pos-sua').val(trichXuatSoLieu(bc, 'Pos')); $('#aeplus-sua').val(trichXuatSoLieu(bc, ['AE+', 'AE Plus']));
            $('#mtd-sua').val(trichXuatSoLieu(bc, 'MTD MC'));
            modalSuaBaoCao.show();
        }
    });

    $('#nut-xac-nhan-sua-bao-cao').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const n = parseInt($('#ntb-sua').val()) || 0, e = parseInt($('#etb-sua').val()) || 0;
            nv.baoCao = `Fos ${nv.ten}\nTổng MC: ${n+e}\nNTB: ${n}\nETB: ${e}\nAE+: ${$('#aeplus-sua').val() || 0}\nPos: ${$('#pos-sua').val() || 0}\nMTD MC: ${$('#mtd-sua').val() || 0}`;
            nv.trangThai = 'Đã báo cáo'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalSuaBaoCao.hide();
        }
    });

    $('#nut-dan-tu-bo-nho').on('click', async () => {
        try { const t = await navigator.clipboard.readText(); if (t) $('#noi-dung-bao-cao-nhap').val(t); } catch(e) {}
    });

    $('#nut-dan-hang-loat').on('click', async () => {
        try { const t = await navigator.clipboard.readText(); if (t) $('#noi-dung-nhieu-bao-cao-nhap').val(t); } catch(e) {}
    });

    $('#nut-xu-ly-nhieu-bao-cao').on('click', () => {
        const vanBan = $('#noi-dung-nhieu-bao-cao-nhap').val().trim();
        if (!vanBan) return;
        const khoiBaoCao = vanBan.split(/(?=^Fos\s)/im); 
        khoiBaoCao.forEach(khoi => {
            const khoiTrim = khoi.trim();
            const nv = danhSachNhanVien.find(n => {
                const tenEscape = n.ten.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
                return new RegExp(`^Fos\\s+${tenEscape}(?=\\s|$)`, 'i').test(khoiTrim);
            });
            if (nv) { nv.baoCao = khoiTrim; nv.trangThai = 'Đã báo cáo'; kiemTraTenTrongBaoCao(nv, khoiTrim); }
        });
        modalDanNhieuBaoCao.hide(); hienThiDanhSachNhanVien(); luuVaoBoNhoTam();
        hienThiThongBao("Đã xử lý xong báo cáo hàng loạt.");
    });

    $('#nut-tao-bao-cao').on('click', () => thucHienTaoBaoCao());
    $('#nut-sao-chep').on('click', function() {
        const $btn = $(this);
        navigator.clipboard.writeText($('#vung-ket-qua-bao-cao').val()).then(() => {
            hienThiThongBao('Đã sao chép báo cáo vào bộ nhớ tạm!');
            $btn.html('<i class="fa-solid fa-check"></i> Đã chép').addClass('btn-success').removeClass('btn-primary');
            setTimeout(() => $btn.html('<i class="fa-regular fa-copy"></i> Sao chép').removeClass('btn-success').addClass('btn-primary'), 2000);
        });
    });

    // --- XỬ LÝ SỰ KIỆN XEM BÁO CÁO CŨ (MỚI) ---
    $('#nut-xem-bao-cao-cu').on('click', async () => {
        hienThiTaiTrang("Đang tải báo cáo cũ...");
        try {
            const homNayStr = dinhDangNgayISO(new Date());
            // Lấy báo cáo có ngày < ngày hôm nay, sắp xếp giảm dần, lấy 1
            const truyVan = `q={"ngayBaoCao": {"$lt": "${homNayStr}"}}&h={"$orderby": {"ngayBaoCao": -1}}&max=1`;
            const duLieu = await thucHienGoiApi(`report?${truyVan}`);

            if (duLieu.length > 0) {
                $('#vung-ket-qua-bao-cao-cu').val(taiTaoNoiDungBaoCao(duLieu[0]));
            } else {
                $('#vung-ket-qua-bao-cao-cu').val("Không tìm thấy dữ liệu báo cáo trước ngày hôm nay.");
            }
            modalXemBaoCaoCu.show();
        } catch (e) {
            hienThiThongBao("Lỗi tải lịch sử: " + e.message, "error");
        } finally {
            anTaiTrang();
        }
    });

    // KHỞI CHẠY
    khoiTaoGiaoDien(); 
    xayDungMenuGiaoDien(); 
    taiDuLieuTuServer(); 
});

/* --- HỆ THỐNG GIAO DIỆN SỬ DỤNG BIẾN CSS --- */

:root {
    /* Mặc định (Fallback) */
    --bg-gradient: #f2f2f7;
    --bg-image: none;
    --card-bg: rgba(255, 255, 255, 0.7);
    --text-primary: #000000;
    --text-secondary: #3C3C4399; /* System Gray 2 */
    --main-title-color: #000000;
    --accent-blue: #007AFF;
    --accent-green: #34C759;
    --accent-red: #FF3B30;
    --accent-gray: #8E8E93;
    --input-bg: rgba(118, 118, 128, 0.12);
    --input-border: rgba(0, 0, 0, 0);
    --btn-fos-bg: rgba(255, 255, 255, 1);
    --btn-fos-border: rgba(0, 0, 0, 0);
    --card-radius: 18px;
    --btn-radius: 12px;
    --backdrop-blur: 20px;
    --shadow-soft: 0 4px 24px rgba(0,0,0,0.06);
}

/* --- 1. iOS 18 (Apple Design Resources) --- */
body.theme-ios18-light {
    --bg-gradient: #F2F2F7; /* System Grouped Background */
    --card-bg: rgba(255, 255, 255, 0.85);
    --text-primary: #000000;
    --text-secondary: rgba(60, 60, 67, 0.6);
    --main-title-color: #000000;
    --accent-blue: #007AFF;
    --input-bg: rgba(118, 118, 128, 0.12);
    --btn-fos-bg: #FFFFFF;
    --card-radius: 20px;
    --backdrop-blur: 30px;
}

body.theme-ios18-dark {
    --bg-gradient: #000000; /* True Black */
    --card-bg: rgba(28, 28, 30, 0.85); /* System Gray 6 */
    --text-primary: #FFFFFF;
    --text-secondary: rgba(235, 235, 245, 0.6);
    --main-title-color: #FFFFFF;
    --accent-blue: #0A84FF;
    --input-bg: rgba(118, 118, 128, 0.24);
    --btn-fos-bg: #1C1C1E; /* System Gray 5 */
    --btn-fos-border: rgba(255, 255, 255, 0.05);
    --card-radius: 20px;
    --backdrop-blur: 30px;
}

/* --- 2. OneUI (Samsung Design) --- */
body.theme-oneui-light {
    --bg-gradient: #F7F7F7;
    --card-bg: #FFFFFF; /* OneUI Cards are solid usually */
    --text-primary: #000000;
    --text-secondary: #585858;
    --main-title-color: #000000;
    --accent-blue: #0072DE; /* Samsung Blue */
    --input-bg: #F0F0F0;
    --btn-fos-bg: #FFFFFF;
    --btn-fos-border: #E0E0E0;
    --card-radius: 26px; /* Super rounded */
    --btn-radius: 24px;
    --backdrop-blur: 0px; /* OneUI uses less glass, more solid */
    --shadow-soft: 0 2px 10px rgba(0,0,0,0.03);
}

body.theme-oneui-dark {
    --bg-gradient: #000000; /* AMOLED Black */
    --card-bg: #1E1E1E; /* Dark Gray Cards */
    --text-primary: #FFFFFF;
    --text-secondary: #999999;
    --main-title-color: #FFFFFF;
    --accent-blue: #3E91FF;
    --input-bg: #2C2C2C;
    --btn-fos-bg: #252525;
    --btn-fos-border: transparent;
    --card-radius: 26px;
    --btn-radius: 24px;
    --backdrop-blur: 0px;
}

/* --- 3. Windows 11 (Fluent Design) --- */
body.theme-window11-light {
    /* Mica Effect Simulation */
    --bg-gradient: linear-gradient(135deg, #F3F3F3 0%, #E8F2FC 100%); 
    --card-bg: rgba(255, 255, 255, 0.75);
    --text-primary: #1A1A1A;
    --text-secondary: #5D5D5D;
    --main-title-color: #1A1A1A;
    --accent-blue: #0067C0;
