    --text-secondary: #A0A0A0;
    --main-title-color: #FFFFFF;
    --accent-blue: #4CC2FF;
    --input-bg: rgba(255, 255, 255, 0.05);
    --input-border: rgba(255, 255, 255, 0.08);
    --btn-fos-bg: rgba(255, 255, 255, 0.06);
    --btn-fos-border: rgba(255, 255, 255, 0.05);
